// Clearline AP: courses organized by College Board CED units and topics, original practice questions,
// free-response prompts with scoring guides, and the geometry for AD-AS, supply-demand and PPC graphs.
// app.js loads this file only when the AP tab opens. No DOM access here, so tests can load it in Node.
(() => {
  "use strict";
  const UNITS = [
    { n: 1, name: "Basic Economic Concepts", topics: [["1.1", "Scarcity"], ["1.2", "Opportunity Cost and the Production Possibilities Curve"], ["1.3", "Comparative Advantage and Gains from Trade"], ["1.4", "Demand"], ["1.5", "Supply"], ["1.6", "Market Equilibrium, Disequilibrium, and Changes in Equilibrium"]] },
    { n: 2, name: "Economic Indicators and the Business Cycle", topics: [["2.1", "The Circular Flow and GDP"], ["2.2", "Limitations of GDP"], ["2.3", "Unemployment"], ["2.4", "Price Indices and Inflation"], ["2.5", "Costs of Inflation"], ["2.6", "Real v. Nominal GDP"], ["2.7", "Business Cycles"]] },
    { n: 3, name: "National Income and Price Determination", topics: [["3.1", "Aggregate Demand (AD)"], ["3.2", "Multipliers"], ["3.3", "Short-Run Aggregate Supply (SRAS)"], ["3.4", "Long-Run Aggregate Supply (LRAS)"], ["3.5", "Equilibrium in the Aggregate Demand-Aggregate Supply (AD-AS) Model"], ["3.6", "Changes in the AD-AS Model in the Short Run"], ["3.7", "Long-Run Self-Adjustment"], ["3.8", "Fiscal Policy"], ["3.9", "Automatic Stabilizers"]] },
    { n: 4, name: "Financial Sector", soon: true, topics: [] },
    { n: 5, name: "Long-Run Consequences of Stabilization Policies", soon: true, topics: [] },
    { n: 6, name: "Open Economy: International Trade and Finance", soon: true, topics: [] }
  ];

  // Questions are written with the correct answer first (c[0], why[0]). Each one gets a fixed shuffle seeded by its id,
  // so the answer lands on A-D evenly and a question always looks the same. Explanations never name a letter.
  const QUESTIONS = [
    {"id":"m1.1-01","t":"1.1","d":1,"q":"Scarcity exists in every economy because","c":["human wants are unlimited while the resources to satisfy them are limited","prices are set too high for most people to afford goods","governments limit how much firms are allowed to produce","there is not enough money printed to buy everything people want"],"why":["Scarcity is the basic gap between unlimited wants and limited land, labor, capital and entrepreneurship.","High prices are a result of scarcity, not its cause; even free goods would face limited resources.","Scarcity would exist with no government at all, because resources themselves are limited.","Money is not a resource; printing more of it does not create more land, labor or capital."]},
    {"id":"m1.1-02","t":"1.1","d":1,"q":"Which of the following is an example of the factor of production called capital?","c":["A delivery truck used by a bakery","Cash a firm keeps in its bank account","A forest that is cut for lumber","An owner's willingness to take business risks"],"why":["Capital means man-made tools and equipment used to produce other goods, like a delivery truck.","Money is financial capital, not economic capital; it does not produce anything by itself.","A forest is a natural resource, so economists classify it as land.","Taking risks and organizing production is entrepreneurship, not capital."]},
    {"id":"m1.1-03","t":"1.1","d":1,"q":"Oil deposits that have not yet been pumped out of the ground are classified as which factor of production?","c":["Land","Capital","Labor","Entrepreneurship"],"why":["Land includes all natural resources, such as oil, minerals and water, in their natural state.","Capital is man-made equipment; untouched oil is a gift of nature, not something produced.","Labor is human effort; oil in the ground involves no human work yet.","Entrepreneurship is the risk-taking that combines resources, not a resource found in nature."]},
    {"id":"m1.1-04","t":"1.1","d":1,"q":"A software developer quits a salaried job to start her own app company, risking her savings on the idea. She is supplying which factor of production?","c":["Entrepreneurship","Labor","Capital","Land"],"why":["Starting a business, organizing resources and bearing the risk of loss is entrepreneurship.","Labor is working for a wage; here she takes on risk and organizes the firm, which is more than labor.","Her savings are money, and money is not economic capital.","Land is natural resources; nothing in her decision is a natural resource."]},
    {"id":"m1.1-05","t":"1.1","d":2,"q":"Which of the following is a positive economic statement?","c":["Raising the minimum wage to $15 would reduce employment of teenage workers.","The government should raise the minimum wage to $15.","A $15 minimum wage would be the fairest policy for workers.","Lawmakers ought to care more about low-wage workers than about business owners."],"why":["A positive statement describes what is or would be, and it can be tested with data, even if it turns out false.","The word should signals a value judgment, which makes the statement normative.","Fairest is an opinion about what is good, so the statement is normative.","Ought to expresses a value judgment about priorities, so the statement is normative."]},
    {"id":"m1.1-06","t":"1.1","d":1,"q":"Which question would most likely be studied in macroeconomics rather than microeconomics?","c":["What causes a nation's unemployment rate to rise?","How does a rise in the price of lumber affect a home builder's costs?","How many workers should a pizza shop hire?","Why did the price of avocados fall last month?"],"why":["Macroeconomics studies the whole economy, including total output, unemployment and the price level.","One firm's costs is a microeconomic question about an individual decision maker.","One firm's hiring choice is microeconomics.","The price of a single good is set in a single market, which is microeconomics."]},
    {"id":"m1.1-07","t":"1.1","d":2,"q":"In a command economy, the question of what goods to produce is mainly answered by","c":["government planners","consumers through the prices they are willing to pay","custom and tradition passed down over generations","private firms competing for profit"],"why":["In a command economy, a central authority decides what, how and for whom to produce.","Prices guiding production describes a market economy.","Customs deciding production describes a traditional economy.","Firms competing for profit is how a market economy decides what to produce."]},
    {"id":"m1.1-08","t":"1.1","d":2,"q":"In a market economy, the question of for whom goods are produced is mainly answered by","c":["who is willing and able to pay the market price","who needs the goods the most, as judged by the government","equal shares given to every household","which households have lived in the country the longest"],"why":["Markets ration goods by price: the goods go to buyers willing and able to pay.","Distribution by government judgment of need describes a command economy.","Equal shares is a planned rule, not how markets distribute goods.","Distribution by custom or status describes a traditional economy."]},
    {"id":"m1.1-09","t":"1.1","d":2,"q":"Even a very wealthy country faces scarcity because","c":["its resources are still limited compared to what its people want","wealthy countries have more shortages of goods than poor countries","wealth makes resources less productive","scarcity only applies to goods that are imported"],"why":["Scarcity is about limited resources versus unlimited wants, and no country has unlimited resources.","A shortage is a market condition at a price below equilibrium; scarcity is a different, permanent condition.","Wealth does not reduce productivity; the issue is that resources are finite.","Scarcity applies to every good that uses resources, imported or not."]},
    {"id":"m1.1-10","t":"1.1","d":3,"q":"A student is deciding how many hours to study. The 3rd hour gives a marginal benefit worth 20 and a marginal cost of 15. The 4th hour gives a marginal benefit worth 12 and a marginal cost of 15. Using marginal analysis, how many hours should the student study?","c":["3 hours","4 hours","2 hours","As many hours as possible, since total benefit keeps rising"],"why":["Keep going while marginal benefit is at least marginal cost: the 3rd hour passes (20 > 15) but the 4th does not (12 < 15).","The 4th hour adds less benefit (12) than it costs (15), so it makes the student worse off.","Stopping at 2 skips the 3rd hour, which adds more benefit than cost.","Rising total benefit does not matter; each extra hour must add more benefit than it costs."]},
    {"id":"m1.2-01","t":"1.2","d":1,"q":"Using the production possibilities curve shown, which point is unattainable with the economy's current resources and technology?","g":{"k":"ppc","ppc":1,"x":"Food","y":"Machines","pts":[[40,40,"A"],[56.6,56.6,"B"],[70,70,"C"]],"alt":"Bowed-out PPC with point A inside the curve, point B on the curve and point C outside the curve."},"c":["Point C","Point A","Point B","Every labeled point is attainable"],"why":["Point C lies outside the curve, so the economy cannot produce it with its current resources and technology.","Point A is inside the curve, so it is attainable, just inefficient.","Point B is on the curve, so it is attainable and efficient.","Points outside the PPC cannot be reached without more resources or better technology."]},
    {"id":"m1.2-02","t":"1.2","d":2,"q":"The economy shown is producing at point U. Which statement best describes point U?","g":{"k":"ppc","ppc":1,"x":"Consumer goods","y":"Capital goods","pts":[[35,30,"U"],[56.6,56.6,"E"]],"alt":"Bowed-out PPC with point U inside the curve and point E on the curve."},"c":["Some resources are unemployed or used inefficiently","The economy is using all resources efficiently","The economy cannot reach this point with its current resources","The PPC must have shifted inward"],"why":["A point inside the PPC means the economy could make more of both goods, so resources are idle or wasted.","Full and efficient use of resources puts the economy on the curve, not inside it.","Unattainable points lie outside the curve; U is inside.","Unemployment moves the economy to a point inside an unchanged curve; the curve itself only shifts when resources or technology change."]},
    {"id":"m1.2-03","t":"1.2","d":2,"q":"A production possibilities curve is bowed outward (concave to the origin). This shape shows","c":["increasing opportunity cost, because resources are not equally suited to producing both goods","constant opportunity cost, because resources are equally suited to both goods","decreasing opportunity cost, because workers get better with practice","that the economy is producing inefficiently"],"why":["As more of one good is made, less suitable resources must be shifted over, so each extra unit costs more of the other good.","Constant opportunity cost gives a straight-line PPC, not a bowed-out one.","Decreasing opportunity cost would bow the curve inward, toward the origin.","The shape of the curve says nothing about efficiency; efficiency depends on whether the point is on the curve."]},
    {"id":"m1.2-04","t":"1.2","d":2,"q":"The production possibilities curve for an economy is a straight line, as shown. What does this tell you?","g":{"k":"ppc","ppc":1,"line":true,"x":"Bread","y":"Cakes","alt":"Straight-line PPC running from the vertical axis down to the horizontal axis."},"c":["The opportunity cost of bread in terms of cakes is the same at every point","The opportunity cost of bread rises as more bread is produced","The economy has no opportunity cost of producing bread","The economy is not using its resources efficiently"],"why":["A straight line has a constant slope, so each extra unit of bread always costs the same amount of cakes.","Rising opportunity cost produces a bowed-out curve, not a straight line.","Any point on the line still requires giving up cakes to get more bread, so the cost is not zero.","Points on the line are efficient; the line's shape is not about efficiency."]},
    {"id":"m1.2-05","t":"1.2","d":2,"q":"An economy moves along its PPC from producing 20 robots and 100 tons of corn to producing 30 robots and 70 tons of corn. What is the opportunity cost of each of the additional robots?","c":["3 tons of corn","30 tons of corn","1/3 ton of corn","10 tons of corn"],"why":["Gaining 10 robots cost 30 tons of corn, so each robot costs 30 ÷ 10 = 3 tons.","30 tons is the total cost of all 10 extra robots, not the cost per robot.","1/3 is the cost of a ton of corn measured in robots; the ratio is flipped.","10 is the number of extra robots, not what was given up for each one."]},
    {"id":"m1.2-06","t":"1.2","d":3,"q":"An economy can produce these combinations of tractors and wheat (in tons): 0 tractors and 50 wheat; 10 tractors and 45 wheat; 20 tractors and 35 wheat; 30 tractors and 20 wheat; 40 tractors and 0 wheat. What is the total opportunity cost of increasing tractor production from 20 to 30?","c":["15 tons of wheat","35 tons of wheat","20 tons of wheat","10 tractors"],"why":["Wheat falls from 35 to 20 tons, so 15 tons of wheat are given up for the 10 extra tractors.","35 tons is the wheat produced at 20 tractors, not the amount given up.","20 tons is the wheat left over at 30 tractors, not the amount given up.","Opportunity cost of tractors is measured in the other good, wheat, not in tractors gained."]},
    {"id":"m1.2-07","t":"1.2","d":2,"q":"A major earthquake permanently destroys a large share of a country's factories and equipment. Which graph best shows the effect on the country's production possibilities curve?","c":[{"g":{"k":"ppc","ppc":[1,0.8],"x":"Consumer goods","y":"Capital goods","alt":"The whole PPC shifts inward, toward the origin."}},{"g":{"k":"ppc","ppc":[1,1.25],"x":"Consumer goods","y":"Capital goods","alt":"The whole PPC shifts outward, away from the origin."}},{"g":{"k":"ppc","ppc":[1,[1.3,1]],"x":"Consumer goods","y":"Capital goods","alt":"The PPC pivots outward along the consumer goods axis only."}},{"g":{"k":"ppc","ppc":[1,[1,1.3]],"x":"Consumer goods","y":"Capital goods","alt":"The PPC pivots outward along the capital goods axis only."}}],"why":["Losing productive resources lowers the most the economy can make of both goods, so the whole PPC shifts inward.","An outward shift means more resources or better technology, the opposite of what happened.","This shows growth in the ability to make consumer goods, not a loss of resources.","This shows growth in the ability to make capital goods, not a loss of resources."]},
    {"id":"m1.2-08","t":"1.2","d":2,"q":"A new technology makes computer production faster but has no effect on producing food. Computers are on the horizontal axis. Which graph shows the effect on the PPC?","c":[{"g":{"k":"ppc","ppc":[1,[1.3,1]],"x":"Computers","y":"Food","alt":"The PPC pivots outward along the computers axis; the food intercept stays the same."}},{"g":{"k":"ppc","ppc":[1,[1,1.3]],"x":"Computers","y":"Food","alt":"The PPC pivots outward along the food axis; the computers intercept stays the same."}},{"g":{"k":"ppc","ppc":[1,1.25],"x":"Computers","y":"Food","alt":"The whole PPC shifts outward on both axes."}},{"g":{"k":"ppc","ppc":[1,0.8],"x":"Computers","y":"Food","alt":"The whole PPC shifts inward on both axes."}}],"why":["Only the maximum number of computers rises, so the curve pivots out along the computer axis while the food intercept stays put.","This shows better food technology; the stem says food production is unaffected.","A parallel-style outward shift on both axes needs growth that helps both goods.","An inward shift means lost resources, but the economy gained technology."]},
    {"id":"m1.2-09","t":"1.2","d":3,"q":"The graph shows an economy's PPC for consumer goods and capital goods. If the economy produces at one of the labeled points this year, which choice will most likely lead to the greatest increase in its production possibilities in the future?","g":{"k":"ppc","ppc":1,"x":"Consumer goods","y":"Capital goods","pts":[[72,34.9,"A"],[30,74.2,"B"],[40,30,"C"]],"alt":"Bowed-out PPC with point A on the curve with many consumer goods, point B on the curve with many capital goods, and point C inside the curve."},"c":["Point B, because producing more capital goods now adds to future productive capacity","Point A, because producing more consumer goods raises living standards today","Either point on the curve, because all efficient points lead to the same future growth","Point C, because leaving resources unused saves them for the future"],"why":["Capital goods like machines and factories raise future output, so more capital now shifts the PPC out further later.","Consumer goods are used up today and do not add to the economy's capacity to produce.","Efficient points differ in how much capital they build, so they lead to different growth.","Idle labor and machines are wasted; unused labor hours cannot be stored for later."]},
    {"id":"m1.2-10","t":"1.2","d":1,"q":"An economy is producing on its PPC when a recession causes many workers to lose their jobs. With no change in resources or technology, the economy","c":["moves to a point inside its PPC","moves to a point outside its PPC","has its PPC shift inward","moves along its PPC to a different point on the curve"],"why":["Unemployed workers mean resources are idle, so output falls to a point inside the unchanged curve.","Points outside the curve need more resources or better technology, not fewer jobs.","The workers still exist and could work, so the economy's potential, the curve, does not shift.","Moving along the curve means shifting fully used resources between goods; here resources go unused."]},
    {"id":"m1.3-01","t":"1.3","d":2,"q":"Country A can make 10 shirts or 20 hats per day. Country B can make 6 shirts or 18 hats per day. Which statement about comparative advantage is correct?","c":["Country A has a comparative advantage in shirts and Country B in hats","Country B has a comparative advantage in shirts and Country A in hats","Country A has a comparative advantage in both goods","Neither country has a comparative advantage, because Country A can make more of both goods"],"why":["A shirt costs Country A 2 hats but costs Country B 3 hats, so A has the lower cost in shirts and B the lower cost in hats.","This flips the opportunity costs; Country B gives up more hats for each shirt.","A country cannot have a lower opportunity cost in both goods; that only happens with absolute advantage.","Making more of both goods is absolute advantage; comparative advantage depends on opportunity cost, and it always exists when costs differ."]},
    {"id":"m1.3-02","t":"1.3","d":2,"q":"Country A can make 10 shirts or 20 hats per day. Country B can make 6 shirts or 18 hats per day. What is Country B's opportunity cost of producing 1 hat?","c":["1/3 of a shirt","3 shirts","1/2 of a shirt","6 shirts"],"why":["Country B gives up 6 shirts to make 18 hats, so each hat costs 6 ÷ 18 = 1/3 shirt.","3 is the cost of a shirt in hats; the ratio is upside down.","1/2 shirt is Country A's opportunity cost of a hat, not Country B's.","6 shirts is what Country B gives up for all 18 hats, not for one hat."]},
    {"id":"m1.3-03","t":"1.3","d":3,"q":"Country A can make 10 shirts or 20 hats per day. Country B can make 6 shirts or 18 hats per day. Each country specializes based on comparative advantage. Which terms of trade would benefit both countries?","c":["1 shirt for 2.5 hats","1 shirt for 1.5 hats","1 shirt for 3.5 hats","1 hat for 2.5 shirts"],"why":["A shirt costs Country A 2 hats and Country B 3 hats, so any price between 2 and 3 hats per shirt helps both.","Country A, the shirt seller, would get fewer hats (1.5) than it gives up making a shirt (2), so it loses.","Country B, the shirt buyer, would pay more (3.5 hats) than it costs to make a shirt itself (3), so it loses.","This flips the trade; Country B would give 2.5 shirts per hat when a hat costs it only 1/3 shirt to make."]},
    {"id":"m1.3-04","t":"1.3","d":3,"q":"In Country X, a worker needs 4 hours to make a bike and 2 hours to make a radio. In Country Y, a worker needs 6 hours to make a bike and 2 hours to make a radio. Which statement is correct?","c":["Country X has a comparative advantage in bikes and Country Y in radios","Country Y has a comparative advantage in bikes and Country X in radios","Country X has a comparative advantage in both goods","Country Y has a comparative advantage in bikes because it spends more hours on them"],"why":["With input data, a bike costs X 4 ÷ 2 = 2 radios and costs Y 6 ÷ 2 = 3 radios, so X is the low-cost bike maker and Y the low-cost radio maker.","This treats hours like output; more hours per unit means a higher cost, not an advantage.","One country cannot have the lower opportunity cost in both goods.","Needing more hours per bike is a disadvantage; fewer hours per unit means lower cost."]},
    {"id":"m1.3-05","t":"1.3","d":1,"q":"Two countries can both gain from specialization and trade as long as","c":["their opportunity costs of producing the goods differ","one country has an absolute advantage in both goods","both countries produce the same amount of each good","each country has an absolute advantage in one good"],"why":["Gains from trade come from comparative advantage, which exists whenever opportunity costs differ.","Absolute advantage in both goods does not stop trade from helping; comparative advantage still decides.","Equal output is not required; what matters is different opportunity costs.","Trade can help even when one country has absolute advantage in both goods, so this is not required."]},
    {"id":"m1.3-06","t":"1.3","d":2,"q":"The graph shows Country P's straight-line PPC. Country P specializes in wheat, produces at point S, then trades some wheat for cloth and ends up consuming at point T. What does point T show?","g":{"k":"ppc","ppc":1,"line":true,"x":"Wheat","y":"Cloth","pts":[[80,0,"S"],[50,45,"T"]],"alt":"Straight-line PPC; point S sits where the line meets the wheat axis, and point T lies outside the line."},"c":["Trade lets Country P consume a combination beyond its own production possibilities","Country P's PPC has shifted outward because of trade","Country P is using its resources inefficiently","Country P is now producing the combination at point T"],"why":["Specializing and trading lets a country consume outside its PPC, which is the gain from trade.","Trade does not change the country's resources or technology, so its PPC stays the same.","Inefficiency is a point inside the PPC; T is outside it.","Country P produces at S; T is what it consumes after trading, which it could not produce alone."]},
    {"id":"m1.3-07","t":"1.3","d":2,"q":"The graph shows Country R's straight-line PPC. If all resources go to one good, Country R can make either 80 units of wheat or 80 units of cloth. What is Country R's opportunity cost of producing 1 unit of wheat?","g":{"k":"ppc","ppc":1,"line":true,"x":"Wheat","y":"Cloth","alt":"Straight-line PPC running from 80 units on the cloth axis to 80 units on the wheat axis."},"c":["1 unit of cloth","80 units of cloth","0 units of cloth, since the PPC is straight","1/80 unit of cloth"],"why":["Giving up 80 cloth gets 80 wheat, so each wheat costs 80 ÷ 80 = 1 cloth.","80 cloth is the cost of all 80 units of wheat, not one unit.","A straight PPC means the cost is constant, not zero.","1/80 would be the cost if 80 wheat traded for only 1 cloth; the intercepts are equal."]},
    {"id":"m1.3-08","t":"1.3","d":3,"q":"With the same resources, Alpha can produce 30 cars or 60 computers, and Beta can produce 20 cars or 80 computers. Which statement is correct?","c":["Alpha has both the absolute and the comparative advantage in cars","Beta has the comparative advantage in cars because its opportunity cost of a car is 4 computers","Alpha has the comparative advantage in both goods","Beta has the absolute advantage in both goods"],"why":["Alpha makes more cars (30 vs 20) and a car costs it only 2 computers versus 4 for Beta.","A higher opportunity cost (4 computers) means a disadvantage; the lower cost wins.","No country can have the lower opportunity cost in both goods.","Beta makes more computers but fewer cars, so it has absolute advantage only in computers."]},
    {"id":"m1.3-09","t":"1.3","d":3,"q":"With the same resources, Alpha can produce 30 cars or 60 computers, and Beta can produce 20 cars or 80 computers. Alpha exports cars to Beta at a price of 5 computers per car. Which country is made worse off by this trade?","c":["Beta, because it pays more for a car than its own opportunity cost of 4 computers","Alpha, because it receives more computers than its opportunity cost of 2 computers","Both countries, because the price is outside both opportunity costs","Neither country, because any trade benefits both sides"],"why":["Beta could make a car itself by giving up 4 computers, so paying 5 computers leaves it worse off.","Receiving 5 computers for a car that cost only 2 makes Alpha better off, not worse.","The price is above Alpha's cost, which helps Alpha; only Beta is hurt.","Trade helps both only when the price is between the two opportunity costs (2 and 4 computers)."]},
    {"id":"m1.3-10","t":"1.3","d":1,"q":"A producer has a comparative advantage in a good when it can produce that good","c":["at a lower opportunity cost than another producer","in a larger quantity than another producer using the same resources","using newer technology than another producer","at a higher price than another producer"],"why":["Comparative advantage is about the lowest opportunity cost, meaning giving up the least of other goods.","Producing more with the same resources is absolute advantage.","Technology can affect costs, but the definition is about opportunity cost.","Selling at a higher price is not what comparative advantage means."]},
    {"id":"m1.4-01","t":"1.4","d":1,"q":"According to the law of demand, when the price of a good rises and all else stays the same,","c":["the quantity demanded of the good falls","the demand curve for the good shifts left","the quantity demanded of the good rises","the demand curve for the good shifts right"],"why":["A higher price moves buyers up along the same demand curve to a lower quantity demanded.","The good's own price causes a movement along the curve, not a shift of it.","Buyers want less of a good when it costs more, not more.","A change in the good's own price never shifts its demand curve."]},
    {"id":"m1.4-02","t":"1.4","d":2,"q":"Consumer incomes rise. Movie tickets are a normal good. Which graph shows the market for movie tickets?","c":[{"g":{"k":"sd","d":[0,1],"s":0,"alt":"Demand shifts right from D1 to D2; supply stays put. Price and quantity rise."}},{"g":{"k":"sd","d":[0,-1],"s":0,"alt":"Demand shifts left from D1 to D2; supply stays put. Price and quantity fall."}},{"g":{"k":"sd","d":0,"s":[0,1],"alt":"Supply shifts right from S1 to S2; demand stays put. Price falls and quantity rises."}},{"g":{"k":"sd","d":0,"s":[0,-1],"alt":"Supply shifts left from S1 to S2; demand stays put. Price rises and quantity falls."}}],"why":["For a normal good, higher income increases demand, so the demand curve shifts right.","Demand falls with higher income only for an inferior good.","Buyers' income affects demand, not the sellers' supply.","Income is a demand factor; a supply shift is the wrong curve."]},
    {"id":"m1.4-03","t":"1.4","d":2,"q":"Incomes in a city rise, and as a result fewer people ride the city bus. For these riders, bus rides are","c":["an inferior good","a normal good","a complement to income","a good with an upward-sloping demand curve"],"why":["When demand falls as income rises, the good is inferior.","Demand for a normal good rises when income rises.","Complements are pairs of goods used together, not a good and income.","Demand still slopes down; this is a shift of demand caused by income, not the curve's slope."]},
    {"id":"m1.4-04","t":"1.4","d":2,"q":"Tea and coffee are substitutes. If the price of tea rises, what happens in the market for coffee?","c":["The demand for coffee increases","The demand for coffee decreases","The quantity demanded of coffee decreases, with no shift","The supply of coffee decreases"],"why":["Pricier tea pushes some buyers to switch to coffee, so coffee demand shifts right.","Demand falls when the price of a complement rises, not a substitute.","Only coffee's own price causes a movement along coffee's demand curve.","Tea's price affects coffee buyers, not coffee sellers' costs."]},
    {"id":"m1.4-05","t":"1.4","d":2,"q":"The price of printers falls sharply. Printers and ink cartridges are complements. What happens to the demand for ink cartridges?","c":["It increases, because more people buy printers and need ink","It decreases, because people spend their savings on printers instead","It does not change, because only the price of ink affects ink","It decreases, because ink is now a substitute for printers"],"why":["Cheaper printers mean more printers in use, which raises demand for the ink used with them.","That reasoning fits substitutes; complements are bought together, so their demands move together.","The price of a related good is a demand shifter.","Ink is used with printers, which makes it a complement, not a substitute."]},
    {"id":"m1.4-06","t":"1.4","d":2,"q":"Which of the following causes a movement along the demand curve for pizza rather than a shift of it?","c":["A change in the price of pizza","A change in the price of hamburgers","A change in consumer income","A change in the number of pizza buyers"],"why":["The good's own price changes quantity demanded, which is a movement along the curve.","The price of a related good shifts the whole demand curve.","Income is a determinant of demand, so it shifts the curve.","The number of buyers is a determinant of demand, so it shifts the curve."]},
    {"id":"m1.4-07","t":"1.4","d":3,"q":"Tennis rackets and tennis balls are used together. The price of tennis rackets rises sharply. Which graph shows the market for tennis balls?","c":[{"g":{"k":"sd","d":[0,-1],"s":0,"alt":"Demand shifts left from D1 to D2; supply stays put. Price and quantity fall.","x":"Quantity of tennis balls"}},{"g":{"k":"sd","d":[0,1],"s":0,"alt":"Demand shifts right from D1 to D2; supply stays put. Price and quantity rise.","x":"Quantity of tennis balls"}},{"g":{"k":"sd","d":0,"s":[0,-1],"alt":"Supply shifts left from S1 to S2; demand stays put. Price rises and quantity falls.","x":"Quantity of tennis balls"}},{"g":{"k":"sd","d":0,"s":[0,1],"alt":"Supply shifts right from S1 to S2; demand stays put. Price falls and quantity rises.","x":"Quantity of tennis balls"}}],"why":["Rackets and balls are complements, so pricier rackets mean fewer players and lower demand for balls.","Demand would rise only if rackets were a substitute for balls.","Rackets are not an input for making balls, so the supply of balls does not change.","Nothing lowers the cost of making balls; the change is on the buyers' side."]},
    {"id":"m1.4-08","t":"1.4","d":2,"q":"Shoppers expect the price of televisions to rise sharply next month. What happens to the demand for televisions this month?","c":["It increases","It decreases","It stays the same, but quantity demanded falls","It stays the same, because only the current price matters"],"why":["Buyers rush to purchase before the price goes up, so demand today shifts right.","Expecting higher future prices makes buying now more attractive, not less.","The current price has not changed; expectations shift the whole curve.","Expectations about future prices are a determinant of demand."]},
    {"id":"m1.4-09","t":"1.4","d":1,"q":"Which of the following is NOT a determinant of demand?","c":["The cost of the inputs used to make the good","Consumer tastes and preferences","The prices of related goods","The number of buyers in the market"],"why":["Input costs affect sellers, so they shift supply, not demand.","Tastes are a demand determinant; a fad raises demand.","Prices of substitutes and complements shift demand.","More buyers in a market increase demand."]},
    {"id":"m1.4-10","t":"1.4","d":3,"q":"Movie tickets are a normal good, and streaming services are a substitute for them. Consumer incomes fall, and at the same time the price of streaming subscriptions falls. What happens to the demand for movie tickets?","c":["Demand decreases","Demand increases","The effect on demand cannot be determined","Quantity demanded decreases, but demand does not change"],"why":["Lower income cuts demand for a normal good, and a cheaper substitute also cuts demand, so both push demand left.","Both events lower demand; neither one raises it.","The two effects point the same way, so the direction is certain.","Income and the price of a related good shift demand; neither is the ticket's own price."]},
    {"id":"m1.5-01","t":"1.5","d":1,"q":"According to the law of supply, a higher price for a good, all else equal, leads to","c":["a greater quantity supplied","an increase in supply","a smaller quantity supplied","a decrease in supply"],"why":["A higher price makes producing more profitable, so firms move up the supply curve to a larger quantity.","The good's own price moves along the supply curve; it does not shift it.","Sellers offer more, not less, at higher prices.","A change in the good's own price never shifts its supply curve."]},
    {"id":"m1.5-02","t":"1.5","d":2,"q":"The wages paid to workers in the furniture industry rise. What happens in the market for furniture?","c":["Supply decreases","Supply increases","Demand decreases","Quantity supplied decreases with no shift in supply"],"why":["Higher input costs make each unit more costly to produce, so the supply curve shifts left.","Costlier inputs reduce supply; they do not increase it.","Wages paid by furniture makers affect sellers, not buyers' demand.","Input costs are a supply determinant, so the whole curve shifts."]},
    {"id":"m1.5-03","t":"1.5","d":2,"q":"A new machine cuts the cost of producing solar panels. What is the effect on the solar panel market?","c":["Supply increases","Supply decreases","Demand increases","Quantity supplied increases with no shift in supply"],"why":["Better technology lowers production costs, so firms supply more at every price and the curve shifts right.","Lower costs raise supply, not lower it.","The machine changes sellers' costs, not buyers' desire for panels.","Technology is a supply determinant, so the whole curve shifts, not a movement along it."]},
    {"id":"m1.5-04","t":"1.5","d":2,"q":"A severe drought destroys much of this year's wheat crop. Which graph shows the market for wheat?","c":[{"g":{"k":"sd","d":0,"s":[0,-1],"alt":"Supply shifts left from S1 to S2; demand stays put. Price rises and quantity falls.","x":"Quantity of wheat"}},{"g":{"k":"sd","d":0,"s":[0,1],"alt":"Supply shifts right from S1 to S2; demand stays put. Price falls and quantity rises.","x":"Quantity of wheat"}},{"g":{"k":"sd","d":[0,-1],"s":0,"alt":"Demand shifts left from D1 to D2; supply stays put. Price and quantity fall.","x":"Quantity of wheat"}},{"g":{"k":"sd","d":[0,1],"s":0,"alt":"Demand shifts right from D1 to D2; supply stays put. Price and quantity rise.","x":"Quantity of wheat"}}],"why":["The drought cuts what farmers can grow, so supply shifts left: higher price, lower quantity.","A drought reduces supply; it does not increase it.","Buyers still want wheat; the drought hits sellers, not demand.","The drought does not make buyers want more wheat."]},
    {"id":"m1.5-05","t":"1.5","d":2,"q":"The market price of strawberries rises because demand increased. For strawberry growers, this causes","c":["an increase in quantity supplied","an increase in supply","a decrease in supply","no change in the amount growers offer for sale"],"why":["A higher price moves growers up along their existing supply curve, so quantity supplied rises.","A price change alone is a movement along the supply curve, not a shift of it.","Nothing raised growers' costs, so supply does not fall.","Growers do respond to the higher price by offering more."]},
    {"id":"m1.5-06","t":"1.5","d":2,"q":"The government gives corn farmers a subsidy of $1 for every bushel they produce. What is the effect on the market for corn?","c":["Supply increases","Supply decreases","Demand increases","Demand decreases"],"why":["A per-unit subsidy lowers producers' cost of each bushel, so supply shifts right.","Supply decreases with a per-unit tax, the opposite of a subsidy.","The subsidy goes to producers, so it shifts supply, not demand.","Nothing about the subsidy makes buyers want less corn."]},
    {"id":"m1.5-07","t":"1.5","d":2,"q":"Oil producers expect the price of oil to be much higher next year. What happens to the supply of oil this year?","c":["It decreases, because producers hold some oil back to sell later","It increases, because producers want to sell before prices change","It does not change, because only the current price affects supply","Demand for oil decreases instead"],"why":["If oil will sell for more later, producers store some now, which shifts this year's supply left.","Selling now would make sense only if prices were expected to fall.","Producer expectations about future prices are a supply determinant.","The expectation here belongs to producers, so it affects supply, not demand."]},
    {"id":"m1.5-08","t":"1.5","d":3,"q":"A farmer can use the same land to grow either corn or soybeans. The price of soybeans rises sharply. What happens in the market for corn?","c":["The supply of corn decreases","The supply of corn increases","The demand for corn increases","The quantity supplied of corn increases, with no shift"],"why":["Soybeans become more profitable, so farmers move land out of corn, shifting the corn supply curve left.","Farmers switch toward the good with the higher price, which means less corn, not more.","This is a decision by producers about what to grow, not by buyers of corn.","Corn's own price has not changed, so this is a shift of corn supply, not a movement along it."]},
    {"id":"m1.5-09","t":"1.5","d":2,"q":"The graph shows the market for bottled water. Which of the following could cause the change shown?","g":{"k":"sd","d":0,"s":[0,1],"alt":"Supply shifts right from S1 to S2 while demand stays put; price falls and quantity rises.","x":"Quantity of bottled water"},"c":["More firms enter the bottled water industry","The price of plastic bottles rises","Consumer incomes rise","The price of bottled water rises"],"why":["More sellers mean more water offered at every price, which shifts supply right.","Pricier bottles raise costs and shift supply left, not right.","Income changes shift demand, but the graph shows only supply moving.","A change in the good's own price moves along a curve; it does not shift one."]},
    {"id":"m1.5-10","t":"1.5","d":3,"q":"The price of crude oil, the main input in making gasoline, falls sharply. Which graph shows the market for gasoline?","c":[{"g":{"k":"sd","d":0,"s":[0,1],"alt":"Supply shifts right from S1 to S2; demand stays put. Price falls and quantity rises.","x":"Quantity of gasoline"}},{"g":{"k":"sd","d":0,"s":[0,-1],"alt":"Supply shifts left from S1 to S2; demand stays put. Price rises and quantity falls.","x":"Quantity of gasoline"}},{"g":{"k":"sd","d":[0,1],"s":0,"alt":"Demand shifts right from D1 to D2; supply stays put. Price and quantity rise.","x":"Quantity of gasoline"}},{"g":{"k":"sd","d":[0,-1],"s":0,"alt":"Demand shifts left from D1 to D2; supply stays put. Price and quantity fall.","x":"Quantity of gasoline"}}],"why":["Cheaper crude oil lowers the cost of making gasoline, so supply shifts right.","Supply falls when input costs rise, not when they fall.","Crude oil is an input for refiners, so it affects supply, not drivers' demand.","Lower input costs do not make drivers want less gasoline."]},
    {"id":"m1.6-01","t":"1.6","d":1,"q":"If the market price of a good is above the equilibrium price, there will be","c":["a surplus, and the price will tend to fall","a shortage, and the price will tend to rise","a surplus, and the price will tend to rise","a shortage, and the price will tend to fall"],"why":["Above equilibrium, quantity supplied exceeds quantity demanded, and sellers cut prices to clear the extra goods.","Shortages happen when the price is below equilibrium.","Sellers with unsold goods lower prices, not raise them.","Above equilibrium there is extra product, not too little."]},
    {"id":"m1.6-02","t":"1.6","d":2,"q":"In the market for notebooks, at a price of $6, the quantity demanded is 40 and the quantity supplied is 70. Which statement describes this market at $6?","c":["There is a surplus of 30 notebooks","There is a shortage of 30 notebooks","There is a surplus of 70 notebooks","There is a shortage of 40 notebooks"],"why":["Quantity supplied minus quantity demanded is 70 - 40 = 30 extra notebooks, a surplus.","A shortage needs quantity demanded to exceed quantity supplied; here supply is larger.","The surplus is the gap between the two quantities, not the total quantity supplied.","Quantity demanded is less than quantity supplied, so this is not a shortage."]},
    {"id":"m1.6-03","t":"1.6","d":2,"q":"A city sets a maximum legal rent for apartments that is below the equilibrium rent. What is the most likely result?","c":["A shortage of apartments","A surplus of apartments","No effect, because the ceiling is below equilibrium","An increase in the supply of apartments"],"why":["A binding price ceiling raises quantity demanded and lowers quantity supplied, leaving a shortage.","Surpluses come from price floors set above equilibrium.","A ceiling has no effect only when it is above equilibrium; below equilibrium it binds.","Lower allowed rent reduces quantity supplied; it does not shift supply right."]},
    {"id":"m1.6-04","t":"1.6","d":2,"q":"The government sets a minimum wage above the equilibrium wage in a labor market. What results?","c":["A surplus of labor, meaning more people want jobs than firms want to hire","A shortage of labor, meaning firms cannot find enough workers","No change in employment, because the floor is above equilibrium","An increase in the demand for labor"],"why":["A binding price floor makes quantity supplied of labor exceed quantity demanded, which is unemployment.","A shortage of labor would happen with a wage set below equilibrium.","A floor matters precisely when it is above equilibrium; a floor below equilibrium has no effect.","A higher wage lowers the quantity of labor demanded; it does not shift demand."]},
    {"id":"m1.6-05","t":"1.6","d":1,"q":"The graph shows the market for umbrellas. Compared with the original equilibrium, the new equilibrium has","g":{"k":"sd","d":[0,1],"s":0,"alt":"Demand shifts right from D1 to D2 while supply stays put; the new equilibrium is at a higher price and quantity.","x":"Quantity of umbrellas"},"c":["a higher price and a higher quantity","a higher price and a lower quantity","a lower price and a higher quantity","a lower price and a lower quantity"],"why":["Demand shifting right along a fixed supply curve raises both equilibrium price and quantity.","Higher price with lower quantity comes from supply decreasing, not demand increasing.","Lower price with higher quantity comes from supply increasing.","Both falling comes from demand decreasing, the opposite of what is shown."]},
    {"id":"m1.6-06","t":"1.6","d":2,"q":"A famous athlete is seen riding an electric scooter, and scooters become a fad. Which graph shows the market for electric scooters?","c":[{"g":{"k":"sd","d":[0,1],"s":0,"alt":"Demand shifts right from D1 to D2; supply stays put. Price and quantity rise.","x":"Quantity of scooters"}},{"g":{"k":"sd","d":0,"s":[0,1],"alt":"Supply shifts right from S1 to S2; demand stays put. Price falls and quantity rises.","x":"Quantity of scooters"}},{"g":{"k":"sd","d":[0,-1],"s":0,"alt":"Demand shifts left from D1 to D2; supply stays put. Price and quantity fall.","x":"Quantity of scooters"}},{"g":{"k":"sd","d":0,"s":[0,-1],"alt":"Supply shifts left from S1 to S2; demand stays put. Price rises and quantity falls.","x":"Quantity of scooters"}}],"why":["A change in tastes toward scooters increases demand, raising price and quantity.","The fad affects buyers, not producers' costs, so supply does not shift.","A fad makes buyers want more scooters, not fewer.","Nothing raises the cost of making scooters, so supply does not fall."]},
    {"id":"m1.6-07","t":"1.6","d":2,"q":"In a market with a shortage, which of the following will happen as the market moves to equilibrium?","c":["Price rises, quantity supplied rises and quantity demanded falls","Price falls, quantity supplied falls and quantity demanded rises","Price rises and the demand curve shifts left","Price rises and the supply curve shifts right"],"why":["Buyers bid the price up, which moves sellers up the supply curve and buyers up the demand curve until the gap closes.","Prices fall to fix a surplus, not a shortage.","A price change moves along the demand curve; it does not shift it.","A price change moves along the supply curve; it does not shift it."]},
    {"id":"m1.6-08","t":"1.6","d":3,"q":"In the market for laptops, demand increases while supply also increases. What happens to the equilibrium price and quantity?","c":["Quantity increases; the change in price cannot be determined","Price increases; the change in quantity cannot be determined","Price and quantity both increase","Price decreases; quantity increases"],"why":["Both shifts raise quantity, but more demand pushes price up while more supply pushes it down, so price depends on which shift is bigger.","Both shifts raise quantity, so quantity is certain; price is the uncertain one.","This ignores that the supply increase pulls price down.","This ignores that the demand increase pulls price up."]},
    {"id":"m1.6-09","t":"1.6","d":3,"q":"A frost destroys much of the orange crop, and at the same time a study reports that orange juice helps prevent colds. Which graph could show the market for orange juice?","c":[{"g":{"k":"sd","d":[0,1],"s":[0,-1],"alt":"Demand shifts right from D1 to D2 and supply shifts left from S1 to S2; price rises.","x":"Quantity of orange juice"}},{"g":{"k":"sd","d":[0,1],"s":[0,1],"alt":"Demand shifts right from D1 to D2 and supply shifts right from S1 to S2; quantity rises.","x":"Quantity of orange juice"}},{"g":{"k":"sd","d":[0,-1],"s":[0,-1],"alt":"Demand shifts left from D1 to D2 and supply shifts left from S1 to S2; quantity falls.","x":"Quantity of orange juice"}},{"g":{"k":"sd","d":[0,-1],"s":[0,1],"alt":"Demand shifts left from D1 to D2 and supply shifts right from S1 to S2; price falls.","x":"Quantity of orange juice"}}],"why":["The frost cuts supply (left) and the health news raises demand (right), so price rises for sure.","The frost reduces supply; it does not increase it.","The health study makes buyers want more juice, not less.","This reverses both shifts: frost lowers supply and good news raises demand."]},
    {"id":"m1.6-10","t":"1.6","d":3,"q":"The price of chicken feed rises, and at the same time a popular diet tells people to stop eating eggs. What happens to the equilibrium price and quantity of eggs?","c":["Quantity decreases; the change in price cannot be determined","Price decreases; the change in quantity cannot be determined","Price and quantity both decrease","Price increases and quantity decreases"],"why":["Supply falls (costlier feed) and demand falls (the diet); both cut quantity, but they push price in opposite directions.","Both shifts lower quantity for certain, so quantity is not the uncertain one.","This ignores that the supply decrease pushes price up.","This ignores that the demand decrease pushes price down."]},
    {"id":"m2.1-01","t":"2.1","d":2,"q":"In one year an economy has consumption of $500 billion, gross private investment of $150 billion, government purchases of $200 billion, exports of $80 billion, imports of $100 billion and government transfer payments of $60 billion. What is GDP?","c":["$830 billion","$890 billion","$930 billion","$870 billion"],"why":["GDP = C + I + G + (X - M) = 500 + 150 + 200 + (80 - 100) = 830. Transfer payments are left out because nothing is produced in exchange.","This adds the $60 billion of transfer payments. Transfers move money around but buy no new output, so they are not in GDP.","This adds exports but forgets to subtract imports. Imports were produced abroad, so they must come out.","This flips net exports to imports minus exports. Net exports are exports minus imports, here -20."]},
    {"id":"m2.1-02","t":"2.1","d":1,"q":"Which of the following is counted in this year's GDP?","c":["A house built and sold to a family this year","The purchase of a used car from a neighbor","A Social Security check sent to a retiree","A household's purchase of shares of stock"],"why":["A newly built house is new final output produced this year, counted as investment.","A used car was counted in GDP the year it was made; reselling it adds no new production.","Social Security is a transfer payment. No good or service is produced in exchange.","Buying stock is a financial transaction that changes who owns an asset; nothing new is produced."]},
    {"id":"m2.1-03","t":"2.1","d":1,"q":"Which of the following is NOT counted separately in GDP?","c":["Steel sold to an automaker and used in cars sold this year","A new car bought by a household","New machinery bought by a factory","Salaries a city pays to its police officers"],"why":["The steel is an intermediate good. Its value is already inside the price of the finished car, so counting it again would double count.","A new car bought by a household is a final good counted as consumption.","New machinery is a capital good counted as investment.","Government purchases of services, such as police work, are counted in G."]},
    {"id":"m2.1-04","t":"2.1","d":2,"q":"A farmer sells wheat to a miller for $1. The miller sells the flour to a baker for $3. The baker sells the bread to a consumer for $7. By how much do these transactions add to GDP?","c":["$7","$11","$6","$4"],"why":["Only the final sale counts: $7. Adding the value added at each stage gives the same answer: 1 + (3 - 1) + (7 - 3) = 7.","This adds every sale, 1 + 3 + 7 = 11, which counts the wheat and flour more than once.","This counts the value added by the miller and baker (2 + 4) but leaves out the farmer's $1.","This is only the baker's value added, 7 - 3 = 4."]},
    {"id":"m2.1-05","t":"2.1","d":1,"q":"In the simple circular-flow model, which statement about households is correct?","c":["They sell factors of production in the factor market and buy goods and services in the product market.","They buy factors of production in the factor market and sell goods and services in the product market.","They sell goods and services in the product market and receive wages from the government only.","They buy factors of production in the product market and sell goods in the factor market."],"why":["Households own labor, land and capital. They sell these in the factor market for income, then spend that income in the product market.","This swaps the roles: firms buy factors and sell goods, not households.","In the basic model households earn income from firms in the factor market; they do not sell output.","This mixes up the markets: factors trade in the factor market and goods in the product market."]},
    {"id":"m2.1-06","t":"2.1","d":2,"q":"Which of the following is part of the income approach to measuring GDP?","c":["Interest earned by households on funds lent to firms","Government purchases of goods and services","Net exports","Unemployment benefits paid by the government"],"why":["The income approach adds up incomes earned in production: wages, rent, interest and profit. Interest is one of them.","Government purchases belong to the expenditure approach, C + I + G + Xn.","Net exports are also part of the expenditure approach, not the income approach.","Unemployment benefits are transfer payments, not income earned by producing anything."]},
    {"id":"m2.1-07","t":"2.1","d":2,"q":"A car is built in December 2025 but is not sold until March 2026. How does GDP measure this car?","c":["It is counted in 2025 GDP as inventory investment.","It is counted in 2026 GDP as consumption only.","It is not counted until a consumer buys it, so it never enters 2025 GDP.","It is counted in both 2025 and 2026 GDP."],"why":["GDP counts production when it happens. An unsold new good adds to firms' inventories, which count as investment in 2025.","GDP measures when goods are produced, not when they are sold. The 2026 sale replaces inventory, it is not new production.","Unsold output is not ignored; it shows up as an increase in inventories.","Counting it twice would overstate production. In 2026 the sale to the household is offset by the drop in inventories."]},
    {"id":"m2.1-08","t":"2.1","d":2,"q":"A Japanese-owned company produces cars at a factory in Texas. These cars are counted in","c":["U.S. GDP, because they are produced inside the United States","Japan's GDP, because a Japanese company owns the factory","both U.S. and Japanese GDP","neither country's GDP until they are exported"],"why":["GDP counts output produced within a country's borders, no matter who owns the factory.","Ownership does not matter for GDP; location of production does.","Each good is counted once, in the country where it is produced.","Output counts in GDP when it is produced, whether or not it is ever exported."]},
    {"id":"m2.1-09","t":"2.1","d":3,"q":"An economy's GDP is $1,100 billion. Consumption is $700 billion, government purchases are $250 billion and net exports are -$40 billion. What is gross private investment?","c":["$190 billion","$110 billion","$150 billion","$2,090 billion"],"why":["1,100 = 700 + I + 250 + (-40), so I = 1,100 - 700 - 250 + 40 = 190.","This subtracts the net exports instead of adding back the deficit: 1,100 - 700 - 250 - 40 = 110. A negative Xn lowers GDP, so I must be larger.","This ignores net exports entirely: 1,100 - 700 - 250 = 150.","This adds all the numbers together instead of solving for the missing part."]},
    {"id":"m2.1-10","t":"2.1","d":1,"q":"Why is the purchase of newly issued corporate stock NOT included in GDP?","c":["It transfers ownership of a financial asset and does not itself pay for a newly produced good or service.","It counts as investment, and investment is not part of GDP.","Stock purchases are taxed, and taxed spending is left out of GDP.","Only government purchases of stock are included in GDP."],"why":["Buying stock is a financial transaction. Only the spending of those funds on new capital goods would count as investment.","Investment is part of GDP, but in economics it means buying new capital goods, not financial assets.","Taxes have nothing to do with whether spending is counted; plenty of taxed purchases are in GDP.","No one's purchase of stock counts, because no production happens in the trade."]},
    {"id":"m2.1-11","t":"2.1","d":2,"q":"In the expenditure approach, a household's purchase of a newly built home is classified as","c":["investment","consumption","government purchases","not counted, because it is a financial asset"],"why":["New residential construction is counted as investment, even when a household buys it.","Homes last for decades and provide housing services, so new ones are treated as investment rather than consumption.","The buyer is a household, not the government.","A house is a real, newly produced good, not a financial asset like a stock or bond."]},
    {"id":"m2.2-01","t":"2.2","d":1,"q":"Which of the following productive activities is NOT counted in GDP?","c":["A parent caring for their own children at home","A daycare worker paid by a licensed daycare center","A babysitter paid by a family who reports the income","A nurse paid by a hospital"],"why":["Unpaid household work is nonmarket activity. No market sale is recorded, so GDP misses it.","This is a paid, reported market service, so it is counted.","Reported paid babysitting is a market service and is counted.","Hospital nursing is a paid market service and is counted."]},
    {"id":"m2.2-02","t":"2.2","d":2,"q":"In a country, many home repairs are paid for in cash and never reported to the government. Official GDP will tend to","c":["understate the country's actual production","overstate the country's actual production","measure production accurately, because cash payments are still spending","overstate production because the repairs are double counted"],"why":["Unreported work is part of the underground economy. Real output happens but is never recorded, so GDP is too low.","Missing activity can only make measured GDP smaller than true production, not larger.","Spending must be recorded to show up in official statistics. Unreported cash deals are missed.","Unreported repairs are not counted at all, so they cannot be counted twice."]},
    {"id":"m2.2-03","t":"2.2","d":2,"q":"Workers in a country choose to work fewer hours per week and spend more time with family. Output falls slightly. Which statement best describes what GDP shows?","c":["GDP falls, even though people's well-being may have risen, because GDP does not value leisure.","GDP rises, because leisure is counted as consumption.","GDP is unchanged, because the change was voluntary.","GDP falls, and this proves that people are worse off."],"why":["GDP measures market output only. Less work means less output, but the extra leisure has value GDP ignores.","Leisure has no market price, so it is never counted in consumption.","GDP tracks output, not whether a change was chosen. Less output means lower GDP.","Lower GDP does not prove lower well-being; the workers chose more leisure because they value it."]},
    {"id":"m2.2-04","t":"2.2","d":2,"q":"An oil spill pollutes a coastline, and companies spend $2 billion on cleanup. How is measured GDP affected by the cleanup spending?","c":["It rises by the cleanup spending, even though the spill made people worse off.","It falls by $2 billion to account for the damage.","It is unchanged, because cleanup only restores what was lost.","It falls by the full value of the environmental damage."],"why":["Cleanup is paid market activity, so GDP counts it. GDP does not subtract environmental damage, which is why it can overstate well-being.","GDP never subtracts damage; it only adds up market spending on final goods and services.","The cleanup is paid work, so it is counted even though it only repairs harm.","Environmental damage has no market price, so GDP does not subtract it."]},
    {"id":"m2.2-05","t":"2.2","d":1,"q":"Country X and Country Y have the same real GDP per capita. Which statement is accurate?","c":["The typical household could still be much better off in one country, because GDP per capita says nothing about how income is distributed.","Every household in the two countries has the same income.","The two countries must have the same total GDP.","The two countries must have the same quality of life in every respect."],"why":["GDP per capita is an average. If income is spread very unequally, the typical household can earn far less than the average.","An average does not tell you each household's income.","Total GDP also depends on population size, which can differ.","GDP ignores leisure, pollution, health and other parts of quality of life."]},
    {"id":"m2.2-06","t":"2.2","d":2,"q":"Which measure is best for comparing a country's average standard of living across two decades?","c":["Real GDP per capita","Nominal GDP","Nominal GDP per capita","Total real GDP"],"why":["Real GDP removes price changes, and dividing by population adjusts for a growing number of people.","Nominal GDP can rise just because prices rise, and it ignores population.","Per capita is right, but nominal values still include inflation.","Real GDP removes inflation, but a larger population can raise total output without raising average living standards."]},
    {"id":"m2.2-07","t":"2.2","d":2,"q":"A country's real GDP is $600 billion and its population is 40 million. What is real GDP per capita?","c":["$15,000","$1,500","$150,000","$1,500,000"],"why":["600,000,000,000 ÷ 40,000,000 = 15,000.","This drops a zero; 600 billion ÷ 40 million is 15,000, not 1,500.","This adds an extra zero to the correct answer.","This is off by a factor of 100; check the billions and millions carefully."]},
    {"id":"m2.2-08","t":"2.2","d":3,"q":"Two neighbors each used to care for their own children at home. Now each pays the other $500 per month to watch the other's children, and both report the income. The total amount of childcare is unchanged. What happens to measured GDP each month?","c":["It rises by $1,000","It is unchanged, because the amount of childcare did not change","It rises by $500","It falls by $1,000"],"why":["Unpaid care was not counted before. Now two paid market services of $500 each are recorded: 500 + 500 = 1,000.","Actual childcare did not change, but GDP counts only market transactions, so measured GDP rises. This shows a limitation of GDP.","There are two separate paid services, one in each direction, so both payments count.","Nothing was subtracted; the formerly unpaid care was never in GDP to begin with."]},
    {"id":"m2.2-09","t":"2.2","d":2,"q":"Many people use free online map and search services they value highly. Because these services have no price to users, GDP most likely","c":["understates the benefit people get from them","overstates the benefit people get from them","measures their benefit exactly through consumption spending","counts them as government purchases"],"why":["GDP values output at market prices. A service given away free adds little to measured GDP even if people value it a lot.","With no price paid, GDP records too little, not too much.","Users spend nothing on them, so there is no consumption spending to record.","These services are made by private firms, not bought by the government."]},
    {"id":"m2.2-10","t":"2.2","d":1,"q":"Which statement best explains why GDP is an imperfect measure of a society's well-being?","c":["It counts only market production and leaves out things like leisure, household work and environmental damage.","It counts transfer payments twice.","It measures only goods and leaves out services.","It includes the value of used goods resold during the year."],"why":["GDP measures market output. Many things that affect well-being have no market price, so they are left out.","Transfer payments are not counted at all in GDP.","Services are a large part of GDP and are counted.","Used goods are excluded from GDP because they were counted when first produced."]},
    {"id":"m2.3-01","t":"2.3","d":2,"q":"A country has 180 million employed people, 20 million unemployed people and 100 million adults not in the labor force. What is the unemployment rate?","c":["10%","11.1%","6.7%","66.7%"],"why":["Labor force = 180 + 20 = 200 million. Unemployment rate = 20 ÷ 200 × 100 = 10%.","This divides by employed workers (20 ÷ 180) instead of the whole labor force.","This divides by all adults (20 ÷ 300). People not in the labor force do not belong in the denominator.","This is the labor force participation rate, 200 ÷ 300, not the unemployment rate."]},
    {"id":"m2.3-02","t":"2.3","d":2,"q":"A country has an adult population of 250 million. Of these, 141 million are employed and 9 million are unemployed. What is the labor force participation rate?","c":["60%","56.4%","6%","3.6%"],"why":["Labor force = 141 + 9 = 150 million. Participation rate = 150 ÷ 250 × 100 = 60%.","This uses only the employed (141 ÷ 250). The unemployed are also in the labor force.","This is the unemployment rate, 9 ÷ 150.","This divides the unemployed by the adult population (9 ÷ 250), which is not a standard measure."]},
    {"id":"m2.3-03","t":"2.3","d":1,"q":"A worker wants a job but has stopped looking because she believes no jobs are available. In official statistics she is","c":["not in the labor force, so she is not counted as unemployed","counted as unemployed","counted as employed","counted as frictionally unemployed"],"why":["She is a discouraged worker. To be unemployed you must be actively looking, so she is outside the labor force.","The unemployed must be actively searching for work, which she is not.","She has no job, so she cannot be counted as employed.","Frictional unemployment covers people actively searching between jobs; she has stopped searching."]},
    {"id":"m2.3-04","t":"2.3","d":3,"q":"A labor force of 100 million includes 8 million unemployed people. Then 2 million of the unemployed become discouraged and stop looking for work. What is the new unemployment rate?","c":["About 6.1%","6.0%","8.0%","10.0%"],"why":["The unemployed fall to 6 million and the labor force falls to 98 million. 6 ÷ 98 × 100 = 6.1%.","This lowers the unemployed to 6 million but forgets that the labor force also shrinks to 98 million.","Discouraged workers leave the count, so the measured rate changes even though no one found a job.","Discouraged workers are removed from the unemployed, not added to them."]},
    {"id":"m2.3-05","t":"2.3","d":1,"q":"A recent college graduate is actively searching for her first full-time job. She is an example of which type of unemployment?","c":["Frictional","Structural","Cyclical","Seasonal"],"why":["Frictional unemployment is the short-term search time as workers enter the labor force or move between jobs.","Structural unemployment comes from a mismatch between workers' skills or location and available jobs; she just needs time to find a match.","Cyclical unemployment is caused by a downturn in the economy, which the question does not describe.","Seasonal unemployment comes from predictable changes in demand during the year, such as after the holidays."]},
    {"id":"m2.3-06","t":"2.3","d":1,"q":"Bank tellers lose their jobs because customers now use mobile banking apps, and the tellers lack the skills for the new jobs being created. This is an example of","c":["structural unemployment","frictional unemployment","cyclical unemployment","a discouraged worker effect"],"why":["A lasting change in technology made the tellers' skills no longer match the jobs available. That is structural.","Frictional unemployment is short-term search by workers whose skills are still in demand.","Cyclical unemployment comes from a recession lowering demand, not a permanent change in technology.","Discouraged workers have stopped searching; the question says nothing about that."]},
    {"id":"m2.3-07","t":"2.3","d":2,"q":"During a recession, a car factory lays off workers because fewer people are buying new cars. These workers are","c":["cyclically unemployed","structurally unemployed","frictionally unemployed","not in the labor force"],"why":["The job losses come from the drop in total spending during a downturn. That is cyclical unemployment.","Their skills still match car-making jobs; demand fell only because of the recession.","Frictional unemployment is voluntary or normal job search, not layoffs caused by a recession.","If they are looking for work they are in the labor force and counted as unemployed."]},
    {"id":"m2.3-08","t":"2.3","d":2,"q":"In an economy, frictional unemployment is 2%, structural unemployment is 3% and cyclical unemployment is 1.5%. What is the natural rate of unemployment?","c":["5%","6.5%","3.5%","4.5%"],"why":["Natural rate = frictional + structural = 2% + 3% = 5%. Cyclical unemployment is left out.","6.5% is the actual unemployment rate, which includes cyclical unemployment.","This adds frictional and cyclical; structural belongs in the natural rate, cyclical does not.","This adds structural and cyclical; frictional belongs in the natural rate, cyclical does not."]},
    {"id":"m2.3-09","t":"2.3","d":2,"q":"When an economy is producing at full-employment output, which is true?","c":["The unemployment rate equals the natural rate, with only frictional and structural unemployment.","The unemployment rate is zero.","Only cyclical unemployment remains.","Frictional, structural and cyclical unemployment are all zero."],"why":["Full employment means cyclical unemployment is zero. Frictional and structural unemployment always exist.","People are always changing jobs or retraining, so unemployment is never zero.","It is the reverse: cyclical unemployment is the type that disappears at full employment.","Only cyclical unemployment is zero; the other two remain."]},
    {"id":"m2.3-10","t":"2.3","d":2,"q":"A worker who wants a full-time job can only find 15 hours a week of part-time work. In official statistics, this worker is","c":["counted as employed, so the unemployment rate understates how much labor goes unused","counted as unemployed because the job is part-time","not in the labor force","counted as half employed and half unemployed"],"why":["Anyone who did paid work during the survey week counts as employed. Underemployment is hidden in the unemployment rate.","Part-time workers count as employed even if they want more hours.","She is working, so she is in the labor force.","The survey classifies each person as employed, unemployed or not in the labor force; there are no fractions."]},
    {"id":"m2.3-11","t":"2.3","d":3,"q":"A country's unemployment rate is 5%, there are 6 million unemployed people and the adult population is 200 million. What is the labor force participation rate?","c":["60%","57%","3%","95%"],"why":["Labor force = 6 ÷ 0.05 = 120 million. Participation rate = 120 ÷ 200 × 100 = 60%.","This uses only the employed (120 - 6 = 114 million; 114 ÷ 200 = 57%). The unemployed are part of the labor force too.","This divides the unemployed by the adult population, 6 ÷ 200.","This is the share of the labor force that is employed, 100% - 5%, not the participation rate."]},
    {"id":"m2.4-01","t":"2.4","d":2,"q":"A market basket has 10 pizzas and 4 movie tickets. In the base year a pizza costs $8 and a ticket costs $5. This year a pizza costs $10 and a ticket still costs $5. What is this year's CPI?","c":["120","100","83.3","125"],"why":["Base-year basket = 10 × 8 + 4 × 5 = 100. This year = 10 × 10 + 4 × 5 = 120. CPI = 120 ÷ 100 × 100 = 120.","100 is the CPI in the base year, not this year.","This divides base-year cost by current cost (100 ÷ 120). The current cost goes on top.","This uses only the pizza price change (10 ÷ 8 × 100) and ignores that ticket prices did not change."]},
    {"id":"m2.4-02","t":"2.4","d":2,"q":"The CPI rises from 200 to 210 over one year. What is the inflation rate?","c":["5%","10%","4.8%","105%"],"why":["Inflation = (210 - 200) ÷ 200 × 100 = 5%.","10 is the change in index points, not the percent change.","This divides by the new CPI (10 ÷ 210). Divide by the starting value.","105 is the new index as a percent of the old one, not the rate of increase."]},
    {"id":"m2.4-03","t":"2.4","d":1,"q":"In the base year, the value of the consumer price index is always","c":["100","0","1,000","equal to the inflation rate"],"why":["CPI = cost of basket this year ÷ cost in base year × 100. In the base year the two costs match, so CPI = 100.","A CPI of 0 would mean the basket costs nothing.","The index is scaled so the base year equals 100, not 1,000.","The CPI is a price level, not a rate of change."]},
    {"id":"m2.4-04","t":"2.4","d":3,"q":"The CPI was 125 last year and is 150 this year. What was the inflation rate between the two years?","c":["20%","25%","16.7%","50%"],"why":["(150 - 125) ÷ 125 × 100 = 25 ÷ 125 × 100 = 20%.","25 is the change in index points; it must be divided by the starting CPI of 125.","This divides by this year's CPI (25 ÷ 150). Divide by last year's value.","This measures the change since the base year (150 vs 100), not since last year."]},
    {"id":"m2.4-05","t":"2.4","d":2,"q":"When the price of beef rises sharply, many shoppers buy more chicken instead. Because the CPI uses a fixed basket, it tends to","c":["overstate the rise in the cost of living","understate the rise in the cost of living","measure the cost of living exactly","overstate inflation only for goods that did not change price"],"why":["This is substitution bias. The fixed basket assumes people keep buying pricey beef, so the CPI rises more than what people really pay.","Switching to cheaper goods lets consumers avoid some of the price rise, so the CPI is too high, not too low.","The fixed basket misses the switch, which creates a bias.","Substitution bias affects the overall index, not goods whose prices stayed the same."]},
    {"id":"m2.4-06","t":"2.4","d":2,"q":"A laptop costs the same as last year, but this year's model is much faster and lasts longer. If the CPI does not fully adjust for this, it will","c":["overstate inflation, because consumers get more for the same price","understate inflation, because the laptop's price did not change","correctly show zero inflation for laptops","show deflation for laptops"],"why":["Better quality at the same price is like a price cut. Missing that makes the CPI higher than the true cost of living. This is quality-change bias.","The quality gain means the real price fell, so ignoring it pushes measured inflation up, not down.","The measured price shows no change, but quality-adjusted price fell, so zero is too high.","If the CPI does not adjust for quality, it records no price change at all, not a decline."]},
    {"id":"m2.4-07","t":"2.4","d":2,"q":"A useful new product enters the market but is not added to the CPI basket for several years. This causes the CPI to","c":["overstate the increase in the cost of living","understate the increase in the cost of living","overstate real GDP","become equal to the GDP deflator"],"why":["New products give consumers more choice and often fall in price early on. Leaving them out means the CPI misses gains to buyers, so it overstates inflation.","New-product bias pushes the CPI up, not down.","The CPI measures consumer prices; this bias does not directly change real GDP.","The CPI and GDP deflator use different goods and weights; this bias does not make them equal."]},
    {"id":"m2.4-08","t":"2.4","d":3,"q":"A basket has 4 books, 10 coffees and 2 haircuts. In year 1 (the base year) prices are $15 per book, $2.50 per coffee and $20 per haircut. In year 2 prices are $15, $3.50 and $27.50. What is the CPI in year 2?","c":["120","150","83.3","125"],"why":["Year 1 cost = 60 + 25 + 40 = 125. Year 2 cost = 60 + 35 + 55 = 150. CPI = 150 ÷ 125 × 100 = 120.","$150 is the year 2 cost of the basket, not the index. Divide by the base-year cost and multiply by 100.","This divides base-year cost by year 2 cost (125 ÷ 150). Current cost goes on top.","$125 is the base-year cost of the basket; the base-year CPI is 100."]},
    {"id":"m2.4-09","t":"2.4","d":2,"q":"The CPI falls from 160 to 152 over a year. What was the inflation rate?","c":["-5%","-8%","-5.3%","5%"],"why":["(152 - 160) ÷ 160 × 100 = -8 ÷ 160 × 100 = -5%. Prices fell, so this is deflation.","-8 is the change in index points, not the percent change.","This divides by the new CPI (8 ÷ 152). Divide by the starting value, 160.","The index fell, so the rate is negative, not positive."]},
    {"id":"m2.4-10","t":"2.4","d":1,"q":"The consumer price index measures the price of","c":["a fixed basket of goods and services bought by a typical urban consumer","all final goods and services produced in the economy","raw materials and intermediate goods bought by firms","goods exported to other countries"],"why":["The CPI tracks the cost of a set basket of consumer purchases over time.","All final output is covered by the GDP deflator, not the CPI.","Producer price indexes track input costs; the CPI is about what consumers buy.","The CPI covers what domestic consumers buy, including imports, not exports."]},
    {"id":"m2.5-01","t":"2.5","d":2,"q":"A bank makes a loan at a fixed 6% nominal interest rate. Inflation then turns out to be much higher than anyone expected. Who is hurt?","c":["The bank, because it is repaid with dollars that buy less","The borrower, because the interest rate is fixed","Neither, because the nominal interest rate does not change","Both, equally, because prices rose for everyone"],"why":["Unanticipated inflation lowers the real interest rate the lender earns. The bank loses purchasing power and the borrower gains.","A fixed nominal rate helps the borrower here; they repay with cheaper dollars.","The nominal rate stays the same, but the real rate falls, so wealth shifts from lender to borrower.","Unanticipated inflation redistributes: what the lender loses, the borrower gains."]},
    {"id":"m2.5-02","t":"2.5","d":2,"q":"Which person is most likely to be hurt by unexpectedly high inflation?","c":["A retiree living on a fixed pension that is not adjusted for inflation","A homeowner with a fixed-rate mortgage","A worker whose wage has a cost-of-living adjustment","A firm that borrowed money at a fixed interest rate"],"why":["A fixed nominal income buys less when prices rise faster than expected.","A fixed-rate borrower gains, because the debt is repaid with dollars worth less.","A cost-of-living adjustment raises the wage with prices, which protects the worker.","Like any fixed-rate borrower, the firm gains from surprise inflation."]},
    {"id":"m2.5-03","t":"2.5","d":2,"q":"The nominal interest rate on a savings account is 7% and the inflation rate is 3%. What is the real interest rate?","c":["4%","10%","-4%","2.3%"],"why":["Real rate = nominal rate - inflation = 7% - 3% = 4%.","This adds inflation instead of subtracting it.","This subtracts in the wrong order (3% - 7%).","This divides 7 by 3; the real rate is found by subtraction."]},
    {"id":"m2.5-04","t":"2.5","d":3,"q":"A lender expects 2% inflation and wants a 3% real return, so she lends at a 5% nominal rate. Inflation turns out to be 6%. What real interest rate does she actually earn, and who gains?","c":["-1%; the borrower gains","3%; neither side gains","-1%; the lender gains","11%; the lender gains"],"why":["Actual real rate = 5% - 6% = -1%. The lender loses purchasing power and the borrower gains.","3% was the expected real rate; actual inflation was higher than expected, so the real rate fell.","The math is right, but a negative real rate hurts the lender, not helps.","This adds inflation to the nominal rate instead of subtracting it."]},
    {"id":"m2.5-05","t":"2.5","d":1,"q":"During high inflation, a restaurant must reprint its menus every few weeks. This expense is an example of","c":["menu costs","shoe-leather costs","substitution bias","cyclical unemployment"],"why":["Menu costs are the resources spent changing posted prices.","Shoe-leather costs are the costs of holding less cash and making extra trips to the bank.","Substitution bias is a problem with measuring the CPI, not a cost to firms.","Cyclical unemployment comes from a recession, not from reprinting prices."]},
    {"id":"m2.5-06","t":"2.5","d":1,"q":"When inflation is high, people keep less cash on hand and make more frequent trips to the bank. The time and effort spent doing this is called","c":["shoe-leather costs","menu costs","the real interest rate","a cost-of-living adjustment"],"why":["Shoe-leather costs are the resources used to avoid holding money that is losing value.","Menu costs come from changing posted prices, not from managing cash.","The real interest rate is a return on lending, not a cost of handling money.","A cost-of-living adjustment raises payments with inflation; it is not a cost of holding cash."]},
    {"id":"m2.5-07","t":"2.5","d":2,"q":"If inflation is correctly anticipated and fully built into the nominal interest rate on a loan, then","c":["neither the borrower nor the lender gains from the inflation","the borrower gains and the lender loses","the lender gains and the borrower loses","the real interest rate equals the nominal interest rate"],"why":["When the expected inflation matches actual inflation, the real rate is what both sides planned. No wealth is shifted.","Borrowers gain only when inflation is higher than expected.","Lenders gain only when inflation is lower than expected.","The real rate equals the nominal rate only when inflation is zero."]},
    {"id":"m2.5-08","t":"2.5","d":2,"q":"Lenders want a real return of 3% and expect inflation to be 4%. What nominal interest rate will they charge?","c":["7%","1%","-1%","12%"],"why":["Nominal rate = real rate + expected inflation = 3% + 4% = 7%.","This subtracts expected inflation from the real rate.","This subtracts in the other order, which would give lenders a loss.","This multiplies the two rates instead of adding them."]},
    {"id":"m2.5-09","t":"2.5","d":3,"q":"A worker's nominal wage rises by 3% this year while the price level rises by 5%. What happens to the worker's real wage?","c":["It falls by about 2%.","It rises by about 8%.","It rises by about 2%.","It does not change, because the nominal wage rose."],"why":["Change in real wage = 3% - 5% = -2%. Prices rose faster than pay, so the wage buys less.","This adds inflation to the wage change instead of subtracting it.","This subtracts in the wrong order (5% - 3%).","A higher nominal wage can still buy less if prices rise faster."]},
    {"id":"m2.5-10","t":"2.5","d":2,"q":"Which group is LEAST likely to be hurt by unexpectedly high inflation?","c":["Workers whose contracts include automatic cost-of-living adjustments","Retirees on fixed nominal pensions","Banks holding many fixed-rate loans","Savers who keep large amounts of cash"],"why":["Cost-of-living adjustments raise pay along with prices, so real income is protected.","Fixed nominal pensions lose purchasing power when prices rise.","Fixed-rate lenders are repaid in dollars worth less than expected.","Cash earns no interest, so its purchasing power falls as prices rise."]},
    {"id":"m2.6-01","t":"2.6","d":2,"q":"Nominal GDP is $1,200 billion and the GDP deflator is 120. What is real GDP?","c":["$1,000 billion","$1,440 billion","$1,080 billion","$1,200 billion"],"why":["Real GDP = nominal GDP ÷ deflator × 100 = 1,200 ÷ 120 × 100 = 1,000.","This multiplies by 1.2 instead of dividing, adding inflation rather than removing it.","This subtracts the deflator from nominal GDP; the deflator is an index, so you divide by it.","Real equals nominal only when the deflator is 100."]},
    {"id":"m2.6-02","t":"2.6","d":2,"q":"Nominal GDP is $990 billion and real GDP is $900 billion. What is the GDP deflator?","c":["110","90.9","90","10"],"why":["Deflator = nominal ÷ real × 100 = 990 ÷ 900 × 100 = 110.","This divides real by nominal (900 ÷ 990). Nominal goes on top.","This is the dollar gap between nominal and real GDP, not an index.","This is the percent by which prices are above the base year, not the deflator itself."]},
    {"id":"m2.6-03","t":"2.6","d":3,"q":"In year 1 (the base year), nominal GDP is $500 billion. In year 2, nominal GDP is $594 billion and the GDP deflator is 110. What was the growth rate of real GDP?","c":["8%","18.8%","10%","28.8%"],"why":["Year 1 real GDP = 500. Year 2 real GDP = 594 ÷ 110 × 100 = 540. Growth = (540 - 500) ÷ 500 × 100 = 8%.","This is nominal GDP growth, (594 - 500) ÷ 500. It still includes price increases.","This is the rise in the price level, not in real output.","This adds nominal growth and inflation; inflation must be removed, not added."]},
    {"id":"m2.6-04","t":"2.6","d":1,"q":"In the base year, which is true?","c":["Nominal GDP equals real GDP, and the GDP deflator equals 100.","Real GDP is greater than nominal GDP.","The GDP deflator equals 0.","Nominal GDP is always greater than real GDP."],"why":["Real GDP uses base-year prices, so in the base year the two measures match and the deflator is 100.","Real GDP is above nominal only when prices are below base-year prices.","A deflator of 0 would mean prices of zero; the base-year deflator is 100.","Nominal and real GDP use the same prices in the base year, so they are equal."]},
    {"id":"m2.6-05","t":"2.6","d":2,"q":"Nominal GDP rises by 6% and the GDP deflator rises by 4%. Real GDP rises by approximately","c":["2%","10%","1.5%","6%"],"why":["Real growth is about nominal growth minus inflation: 6% - 4% = 2%.","This adds inflation instead of removing it.","This divides 6 by 4; growth rates are subtracted.","6% is nominal growth, which still includes rising prices."]},
    {"id":"m2.6-06","t":"2.6","d":2,"q":"An economy produces only one good. In the base year it sold for $5. This year 200 units are produced and sold for $8 each. What is real GDP this year?","c":["$1,000","$1,600","$2,560","$600"],"why":["Real GDP values this year's output at base-year prices: 200 × $5 = $1,000.","$1,600 = 200 × $8 is nominal GDP, which uses current prices.","This multiplies nominal GDP by the price ratio (1,600 × 1.6) instead of removing the price rise.","This is the dollar effect of the price change (200 × $3), not real output."]},
    {"id":"m2.6-07","t":"2.6","d":2,"q":"An economy produces only one good. Its base-year price was $4. This year 300 units are sold at $5 each. What is this year's GDP deflator?","c":["125","80","1,500","25"],"why":["Nominal = 300 × 5 = 1,500. Real = 300 × 4 = 1,200. Deflator = 1,500 ÷ 1,200 × 100 = 125.","This divides real by nominal (1,200 ÷ 1,500). Nominal goes on top.","$1,500 is nominal GDP, not the price index.","This is the percent rise in price since the base year; the index itself is 125."]},
    {"id":"m2.6-08","t":"2.6","d":2,"q":"Nominal GDP grows by 3% in a year while the GDP deflator rises by 5%. What happened to real GDP?","c":["It fell by about 2%.","It rose by about 8%.","It rose by about 2%.","It rose by 3%."],"why":["Real growth ≈ 3% - 5% = -2%. Higher spending was more than explained by higher prices, so output fell.","This adds inflation to nominal growth instead of subtracting it.","This subtracts in the wrong order.","3% is nominal growth; part of it, and more, came from rising prices."]},
    {"id":"m2.6-09","t":"2.6","d":1,"q":"Why do economists use real GDP rather than nominal GDP to measure economic growth?","c":["Real GDP removes the effect of price changes, so it shows changes in actual output.","Real GDP includes transfer payments, so it is more complete.","Real GDP counts only goods, which are easier to measure than services.","Real GDP is always larger than nominal GDP."],"why":["Nominal GDP can rise just because prices rise. Real GDP holds prices constant, so it tracks the quantity produced.","Neither real nor nominal GDP includes transfer payments.","Real GDP includes services as well as goods.","Real GDP is smaller than nominal GDP whenever prices are above base-year levels."]},
    {"id":"m2.6-10","t":"2.6","d":3,"q":"Real GDP last year was $2,000 billion. This year nominal GDP is $2,520 billion and the GDP deflator is 120. What was the growth rate of real GDP?","c":["5%","26%","20%","4.8%"],"why":["This year's real GDP = 2,520 ÷ 120 × 100 = 2,100. Growth = (2,100 - 2,000) ÷ 2,000 × 100 = 5%.","This compares this year's nominal GDP to last year's real GDP (2,520 vs 2,000), mixing in price changes.","This is how far prices are above the base year, not output growth.","This divides the change by the new value (100 ÷ 2,100). Divide by last year's real GDP."]},
    {"id":"m2.7-01","t":"2.7","d":1,"q":"Which sequence lists the phases of a business cycle in order, starting from a peak?","c":["Peak, contraction, trough, expansion","Peak, trough, contraction, expansion","Peak, expansion, trough, contraction","Peak, contraction, expansion, trough"],"why":["After a peak, output falls (contraction) to a low point (trough), then rises again (expansion) toward the next peak.","The trough is reached at the end of a contraction, not before it.","Output cannot keep rising right after a peak; a peak is where expansion ends.","Expansion begins at the trough, so the trough must come first."]},
    {"id":"m2.7-02","t":"2.7","d":1,"q":"During the contraction phase of a business cycle, real GDP and the unemployment rate typically","c":["fall and rise, respectively","rise and fall, respectively","both rise","both fall"],"why":["Firms produce less, so real GDP falls and they lay off workers, so unemployment rises.","This describes an expansion, not a contraction.","Output falls during a contraction.","Unemployment rises, not falls, when output drops."]},
    {"id":"m2.7-03","t":"2.7","d":2,"q":"The graph shows an economy's current short-run equilibrium. Which statement is correct?","g":{"k":"adas","ad":-1,"sras":0,"lras":0,"alt":"AD-AS graph: AD crosses SRAS to the left of the vertical LRAS, so equilibrium real GDP is below full-employment output."},"c":["Real GDP is below full-employment output and unemployment is above the natural rate.","Real GDP is above full-employment output and unemployment is below the natural rate.","Real GDP is below full-employment output and unemployment is below the natural rate.","The economy is at full employment with zero cyclical unemployment."],"why":["Equilibrium is left of LRAS, a recessionary gap. Producing less than potential means cyclical unemployment, so unemployment is above the natural rate.","That describes an inflationary gap, where equilibrium is to the right of LRAS.","Lower output needs fewer workers, so unemployment rises above the natural rate, not below.","Equilibrium is not on LRAS, so the economy is not at full employment."]},
    {"id":"m2.7-04","t":"2.7","d":2,"q":"The graph shows an economy's current short-run equilibrium. What is true of unemployment?","g":{"k":"adas","ad":1,"sras":0,"lras":0,"alt":"AD-AS graph: AD crosses SRAS to the right of the vertical LRAS, so equilibrium real GDP is above full-employment output."},"c":["It is below the natural rate, because output is above full employment.","It is above the natural rate, because output is above full employment.","It equals the natural rate, because the economy is on SRAS.","It is zero, because output is above full employment."],"why":["Equilibrium is right of LRAS, an inflationary gap. Firms push output past potential by hiring extra workers, so unemployment falls below the natural rate.","Higher output means more hiring, which lowers unemployment.","Short-run equilibrium is always on SRAS; full employment needs equilibrium on LRAS.","Frictional and structural unemployment still exist, so unemployment is never zero."]},
    {"id":"m2.7-05","t":"2.7","d":2,"q":"Which graph shows an economy in a recessionary gap?","c":[{"g":{"k":"adas","ad":-1,"sras":0,"lras":0,"alt":"AD-AS graph: AD and SRAS cross to the left of LRAS."}},{"g":{"k":"adas","ad":1,"sras":0,"lras":0,"alt":"AD-AS graph: AD and SRAS cross to the right of LRAS."}},{"g":{"k":"adas","ad":0,"sras":0,"lras":0,"alt":"AD-AS graph: AD and SRAS cross exactly on LRAS."}},{"g":{"k":"adas","ad":0,"sras":1,"lras":0,"alt":"AD-AS graph: SRAS sits further right, so AD and SRAS cross to the right of LRAS."}}],"why":["A recessionary gap means short-run equilibrium output is to the left of LRAS (below full employment).","Equilibrium to the right of LRAS is an inflationary gap.","Equilibrium on LRAS is long-run equilibrium at full employment, with no gap.","Here output is to the right of LRAS, which is an inflationary gap, not a recessionary one."]},
    {"id":"m2.7-06","t":"2.7","d":2,"q":"Potential (full-employment) output is best described as the level of real GDP produced when","c":["unemployment equals the natural rate","unemployment is zero","the economy is at the peak of a business cycle","all factories run at their absolute maximum capacity"],"why":["Potential output is what the economy produces with only frictional and structural unemployment, at the natural rate.","Some frictional and structural unemployment always exists, even at potential.","At a peak, output is often above potential for a while, creating an inflationary gap.","Actual output can rise above potential for a time by running overtime, so potential is not the absolute maximum."]},
    {"id":"m2.7-07","t":"2.7","d":2,"q":"At the trough of a business cycle, the economy usually has","c":["its lowest real GDP and highest unemployment for that cycle","its highest real GDP and lowest unemployment for that cycle","real GDP equal to potential output","rapidly rising inflation and falling unemployment"],"why":["The trough is the low point of a contraction, where output bottoms out and unemployment is highest.","That describes a peak.","At a trough, output is well below potential, a recessionary gap.","Inflation pressure is weak at a trough because spending and output are low."]},
    {"id":"m2.7-08","t":"2.7","d":3,"q":"An economy's potential real GDP is $20 trillion, and its actual real GDP is $19 trillion. Which describes the output gap?","c":["A recessionary gap of $1 trillion, equal to 5% of potential output","An inflationary gap of $1 trillion, equal to 5% of potential output","A recessionary gap of $1 trillion, equal to about 5.3% of potential output","No gap, because the difference is less than 10%"],"why":["Actual output is below potential: 19 - 20 = -1 trillion. As a share of potential, 1 ÷ 20 × 100 = 5%.","Actual output below potential is a recessionary gap, not an inflationary one.","This divides by actual output (1 ÷ 19). The gap is measured relative to potential output.","Any difference between actual and potential output is an output gap."]},
    {"id":"m2.7-09","t":"2.7","d":2,"q":"On a business cycle graph, the upward-sloping long-run trend line through the ups and downs of real GDP reflects","c":["growth in potential output over time","the rise in the price level over time","the average unemployment rate","the government budget balance"],"why":["The trend shows how full-employment output (LRAS) grows as the economy gains resources and better technology.","Business cycle graphs plot real GDP, which already removes price changes.","Unemployment is not on the vertical axis of a business cycle graph; real GDP is.","The budget balance is not what the trend line measures."]},
    {"id":"m2.7-10","t":"2.7","d":3,"q":"Real GDP in an economy has fallen for three quarters in a row, and the unemployment rate has risen from 4% to 7%. The natural rate of unemployment is 4.5%. Which statement describes the economy?","c":["It is in a contraction, and cyclical unemployment is 2.5%.","It is in an expansion, and cyclical unemployment is 2.5%.","It is in a contraction, and cyclical unemployment is 3%.","It is in a contraction, and cyclical unemployment is 7%."],"why":["Falling real GDP and rising unemployment mark a contraction. Cyclical unemployment = actual rate - natural rate = 7% - 4.5% = 2.5%.","Real GDP is falling, so this is a contraction, not an expansion.","This subtracts the starting rate (7% - 4%) instead of the natural rate.","7% is the total unemployment rate, which still includes frictional and structural unemployment."]},
    {"id":"m3.1-01","t":"3.1","d":1,"q":"Which explanation for the downward slope of the aggregate demand curve is the wealth (real balances) effect?","c":["A higher price level lowers the purchasing power of household wealth, so consumption falls","A higher price level leads buyers to switch to relatively cheaper goods within the economy","A higher price level raises firms' production costs, so they produce less","A higher price level raises nominal incomes, so households spend more"],"why":["When prices rise, the same savings buy less, so people feel poorer and buy less. Quantity of real GDP demanded falls.","Switching between goods is the substitution effect for a single market, not a reason the whole economy buys less.","Production costs are a supply-side idea; they affect SRAS, not why AD slopes down.","This would make AD slope up, and it ignores that higher prices shrink what money and wealth can buy."]},
    {"id":"m3.1-02","t":"3.1","d":1,"q":"According to the interest rate effect, an increase in the price level causes which of the following?","c":["Households and firms demand more money, interest rates rise, and investment spending falls","The central bank lowers interest rates, and investment spending rises","Interest rates fall because savers have more money, and consumption rises","Nominal wages rise, and the SRAS curve shifts left"],"why":["A higher price level means people need more money for purchases. Higher money demand pushes up interest rates, which cuts interest-sensitive spending like investment.","The interest rate effect is automatic through money demand; it does not rely on a central bank decision, and it lowers spending.","This gets the direction backward: higher prices raise money demand and push interest rates up, not down.","Wage changes shift SRAS; the interest rate effect explains the slope of AD."]},
    {"id":"m3.1-03","t":"3.1","d":2,"q":"Holding exchange rates constant, a rise in the domestic price level relative to foreign price levels tends to do which of the following?","c":["Decrease net exports, reducing the quantity of real GDP demanded","Increase net exports, increasing the quantity of real GDP demanded","Shift the aggregate demand curve to the right","Shift the long-run aggregate supply curve to the left"],"why":["Domestic goods become relatively more expensive, so foreigners buy fewer exports and residents buy more imports. That is a movement up along AD.","Higher domestic prices make exports less attractive, so net exports fall, not rise.","A change in the domestic price level moves the economy along AD; it does not shift AD.","LRAS depends on resources and technology, not the price level."]},
    {"id":"m3.1-04","t":"3.1","d":2,"g":{"k":"adas","ad":[0,1],"sras":0,"lras":0,"alt":"AD-AS graph: AD shifts right from AD1 to AD2; SRAS and LRAS stay put."},"q":"The graph shows a change in an economy that started in long-run equilibrium. Which event could have caused it?","c":["The government increases spending on highways and bridges","The price level rises","The price of oil falls sharply","Personal income taxes increase"],"why":["Government purchases are a component of AD (C + I + G + Xn), so more G shifts AD right.","A change in the price level causes a movement along AD, not a shift.","Cheaper oil lowers production costs and shifts SRAS right, not AD.","Higher income taxes cut disposable income and consumption, which shifts AD left."]},
    {"id":"m3.1-05","t":"3.1","d":2,"q":"Which of the following would shift the aggregate demand curve to the left?","c":["A recession in the country's major trading partners","An increase in the domestic price level","An increase in nominal wages","A stock market boom that raises household wealth"],"why":["When trading partners' incomes fall, they buy fewer of this country's exports, so net exports and AD fall.","A higher price level is a movement along AD, not a shift.","Higher nominal wages raise production costs and shift SRAS left, not AD.","More household wealth raises consumption, which shifts AD right."]},
    {"id":"m3.1-06","t":"3.1","d":2,"q":"Business owners become much more optimistic about future sales and increase spending on new equipment. Which graph shows the short-run effect?","c":[{"g":{"k":"adas","ad":[0,1],"sras":0,"lras":0,"alt":"AD shifts right from AD1 to AD2; SRAS and LRAS unchanged."}},{"g":{"k":"adas","ad":[0,-1],"sras":0,"lras":0,"alt":"AD shifts left from AD1 to AD2; SRAS and LRAS unchanged."}},{"g":{"k":"adas","ad":0,"sras":[0,1],"lras":0,"alt":"SRAS shifts right from SRAS1 to SRAS2; AD and LRAS unchanged."}},{"g":{"k":"adas","ad":0,"sras":[0,-1],"lras":0,"alt":"SRAS shifts left from SRAS1 to SRAS2; AD and LRAS unchanged."}}],"why":["Spending on new equipment is investment, a component of AD, so AD shifts right, raising PL and real GDP.","Optimism raises investment, so AD shifts right, not left.","Buying equipment is spending, which shows up first as demand; this graph shows a supply change.","Nothing here raises costs, and the change is in spending, so SRAS does not shift left."]},
    {"id":"m3.1-07","t":"3.1","d":1,"q":"If the price level falls and nothing else changes, what happens in the AD-AS model?","c":["The quantity of real GDP demanded increases, a movement down along the AD curve","The AD curve shifts to the right","The AD curve shifts to the left","The LRAS curve shifts to the right"],"why":["A price level change moves the economy along AD. Lower prices raise real wealth, lower interest rates and boost net exports.","Only a change in a determinant of C, I, G or Xn shifts AD; the price level is on the axis.","A lower price level does not reduce demand, and it moves along AD rather than shifting it.","LRAS depends on resources and technology, not on the price level."]},
    {"id":"m3.1-08","t":"3.1","d":3,"q":"The country's currency appreciates sharply against other currencies. Holding everything else constant, what happens to aggregate demand?","c":["It decreases, because exports fall and imports rise","It increases, because a stronger currency raises household wealth","It does not shift; the economy moves along the AD curve","It increases, because imports become cheaper and imports are part of AD"],"why":["A stronger currency makes exports pricier abroad and imports cheaper at home, so net exports fall and AD shifts left.","A stronger currency does not raise domestic wealth in a way that outweighs the fall in net exports.","An exchange rate change is a determinant of net exports, so it shifts AD rather than moving along it.","Imports are subtracted in Xn = X - M, so more imports lower AD."]},
    {"id":"m3.1-09","t":"3.1","d":2,"q":"Households expect their incomes to rise sharply next year. Which component of AD changes first, and in which direction does AD shift?","c":["Consumption rises, shifting AD right","Investment rises, shifting AD right","Consumption falls as households save for the future, shifting AD left","Government spending rises, shifting AD right"],"why":["Expecting higher income, households spend more now, so consumption rises and AD shifts right.","Investment is business spending on capital; this change is about household spending.","Expecting higher future income leads households to spend more today, not save more.","Household expectations do not directly change government purchases."]},
    {"id":"m3.1-10","t":"3.1","d":3,"g":{"k":"adas","ad":[0,-1],"sras":0,"lras":0,"alt":"AD-AS graph: AD shifts left from AD1 to AD2; SRAS and LRAS stay put."},"q":"The economy starts in long-run equilibrium and then experiences the change shown. Which event is the most likely cause?","c":["A sharp fall in stock prices reduces household wealth","The price level increases","Nominal wages rise across the economy","Personal income taxes are cut"],"why":["Lower wealth cuts consumption, a component of AD, so AD shifts left: PL and real GDP fall.","A price level change is a movement along AD, not a shift.","Higher wages raise production costs and shift SRAS left; the graph shows AD moving.","A tax cut raises disposable income and consumption, shifting AD right, not left."]},
    {"id":"m3.2-01","t":"3.2","d":1,"q":"If the marginal propensity to consume is 0.8, what is the value of the spending multiplier?","c":["5","1.25","4","0.2"],"why":["Spending multiplier = 1/MPS = 1/(1 - 0.8) = 1/0.2 = 5.","1.25 is 1/MPC; the multiplier divides by MPS, not MPC.","4 is the size of the tax multiplier, MPC/MPS = 0.8/0.2.","0.2 is the MPS itself, not the multiplier."]},
    {"id":"m3.2-02","t":"3.2","d":2,"q":"The marginal propensity to save is 0.25. If government spending increases by $20 billion, what is the maximum possible change in real GDP?","c":["An increase of $80 billion","An increase of $26.67 billion","An increase of $60 billion","An increase of $5 billion"],"why":["Multiplier = 1/MPS = 1/0.25 = 4, and 4 × $20 billion = $80 billion.","This uses 1/MPC (1/0.75 = 1.33) instead of 1/MPS.","This uses the tax multiplier (0.75/0.25 = 3); a change in G uses the spending multiplier.","This multiplies by MPS (20 × 0.25) instead of dividing by it."]},
    {"id":"m3.2-03","t":"3.2","d":2,"q":"The marginal propensity to consume is 0.75. If the government cuts taxes by $40 billion, what is the maximum possible change in real GDP?","c":["An increase of $120 billion","An increase of $160 billion","A decrease of $120 billion","An increase of $30 billion"],"why":["Tax multiplier = -MPC/MPS = -0.75/0.25 = -3. A tax change of -$40 billion gives -3 × -40 = +$120 billion.","This uses the spending multiplier (4). Part of a tax cut is saved, so the tax multiplier is smaller.","A tax cut raises spending; the negative sign in the tax multiplier cancels with the negative tax change.","This is only the first round of new consumption (0.75 × 40); it leaves out the multiplier rounds."]},
    {"id":"m3.2-04","t":"3.2","d":3,"q":"The marginal propensity to consume is 0.9. The government increases both spending and taxes by $50 billion. What is the maximum possible change in real GDP?","c":["An increase of $50 billion","An increase of $500 billion","No change","A decrease of $450 billion"],"why":["G adds 10 × 50 = $500 billion and the tax rise subtracts 9 × 50 = $450 billion, a net +$50 billion. The balanced-budget multiplier is 1.","This counts only the spending increase and ignores the tax increase.","The effects do not cancel: the spending multiplier (10) is larger than the tax multiplier (9).","This counts only the tax increase and ignores the extra government spending."]},
    {"id":"m3.2-05","t":"3.2","d":1,"q":"If the marginal propensity to save is 0.1, what is the marginal propensity to consume?","c":["0.9","0.1","10","1.1"],"why":["Each extra dollar of disposable income is either spent or saved, so MPC = 1 - MPS = 1 - 0.1 = 0.9.","This repeats the MPS; MPC and MPS must add to 1.","10 is the spending multiplier (1/MPS), not the MPC.","MPC and MPS add to 1, so MPC cannot exceed 1."]},
    {"id":"m3.2-06","t":"3.2","d":2,"q":"When disposable income rises from $500 to $600, consumption rises from $420 to $500. What is the spending multiplier?","c":["5","0.8","1.25","4"],"why":["MPC = 80/100 = 0.8, so MPS = 0.2 and the multiplier = 1/0.2 = 5.","0.8 is the MPC, not the multiplier.","1.25 is 1/MPC; the multiplier is 1/MPS.","4 is the tax multiplier's size (0.8/0.2), not the spending multiplier."]},
    {"id":"m3.2-07","t":"3.2","d":3,"q":"Real GDP is $200 billion below full-employment output, and the MPC is 0.8. What is the minimum increase in government spending that would close the gap?","c":["$40 billion","$200 billion","$50 billion","$160 billion"],"why":["The spending multiplier is 1/0.2 = 5, so $200 billion ÷ 5 = $40 billion of new spending is enough.","This ignores the multiplier; each dollar of G creates $5 of real GDP.","This divides by the tax multiplier (4); a change in G uses the spending multiplier (5).","This multiplies the gap by MPC instead of dividing by the multiplier."]},
    {"id":"m3.2-08","t":"3.2","d":3,"q":"Real GDP is $200 billion below full-employment output, and the MPC is 0.8. What is the minimum tax cut that would close the gap?","c":["$50 billion","$40 billion","$200 billion","$250 billion"],"why":["The tax multiplier is 0.8/0.2 = 4 in size, so $200 billion ÷ 4 = $50 billion.","This uses the spending multiplier (5); some of a tax cut is saved, so a bigger cut is needed.","This ignores the multiplier entirely.","This divides the gap by MPC (200 ÷ 0.8) instead of by the tax multiplier."]},
    {"id":"m3.2-09","t":"3.2","d":2,"q":"Why is the tax multiplier smaller in absolute value than the spending multiplier?","c":["Part of a tax cut is saved, so first-round spending rises by only MPC times the tax cut","Taxes affect only the price level, not real GDP","Government spending is not subject to the multiplier process","A tax cut is fully spent, while government spending is partly saved"],"why":["Government spending enters the economy in full, but households save MPS of a tax cut, so the first round is smaller.","Tax changes shift AD through consumption, so they change real GDP in the short run.","Government spending is fully multiplied by 1/MPS.","This gets it backward: households save part of a tax cut; government purchases are spent in full."]},
    {"id":"m3.2-10","t":"3.2","d":2,"q":"Investment spending falls by $10 billion. If the MPC is 0.6, what is the maximum change in real GDP?","c":["A decrease of $25 billion","A decrease of $16.67 billion","A decrease of $15 billion","An increase of $25 billion"],"why":["MPS = 0.4, multiplier = 1/0.4 = 2.5, and 2.5 × -$10 billion = -$25 billion.","This uses 1/MPC (1/0.6 = 1.67) instead of 1/MPS.","This uses the tax multiplier (0.6/0.4 = 1.5); a change in investment uses the spending multiplier.","Less investment means less spending, so real GDP falls, not rises."]},
    {"id":"m3.2-11","t":"3.2","d":3,"q":"If the MPC rises from 0.75 to 0.8, what happens to the spending multiplier?","c":["It increases from 4 to 5","It decreases from 5 to 4","It increases from 3 to 4","It stays the same, because MPS does not change"],"why":["MPS falls from 0.25 to 0.2, so 1/MPS rises from 4 to 5. Spending more of each dollar makes each round bigger.","A higher MPC means a lower MPS, which makes the multiplier larger, not smaller.","3 and 4 are the tax multipliers (MPC/MPS) at these values, not the spending multipliers.","MPS = 1 - MPC, so when MPC rises MPS must fall."]},
    {"id":"m3.2-12","t":"3.2","d":2,"g":{"k":"adas","ad":[0,1],"sras":0,"lras":0,"alt":"AD-AS graph: AD shifts right from AD1 to AD2; SRAS and LRAS unchanged."},"q":"The AD shift shown was caused by a $10 billion increase in government spending. If the MPC is 0.75, by how much did the AD curve shift to the right?","c":["$40 billion","$10 billion","$30 billion","$13.33 billion"],"why":["AD shifts right by the full multiplier effect: 1/0.25 = 4, and 4 × $10 billion = $40 billion.","This leaves out the multiplier rounds of extra consumption.","This uses the tax multiplier (3); a change in G uses the spending multiplier (4).","This uses 1/MPC instead of 1/MPS."]},
    {"id":"m3.3-01","t":"3.3","d":1,"q":"Why does the short-run aggregate supply curve slope upward?","c":["Some input prices, such as nominal wages, are slow to adjust, so a higher price level raises profit per unit and firms produce more","A higher price level reduces the real value of wealth, so households buy more","In the short run all prices and wages adjust fully and immediately","A higher price level lowers interest rates, which encourages investment"],"why":["With wages fixed by contracts in the short run, higher output prices make production more profitable, so output rises.","That is the wealth effect, which explains AD, and it says higher prices reduce spending.","If all prices and wages adjusted fully, the curve would be vertical like LRAS.","A higher price level raises interest rates, and this is an AD idea, not SRAS."]},
    {"id":"m3.3-02","t":"3.3","d":2,"q":"The world price of oil rises sharply. Which graph shows the short-run effect on an oil-importing economy?","c":[{"g":{"k":"adas","ad":0,"sras":[0,-1],"lras":0,"alt":"SRAS shifts left from SRAS1 to SRAS2; AD and LRAS unchanged."}},{"g":{"k":"adas","ad":0,"sras":[0,1],"lras":0,"alt":"SRAS shifts right from SRAS1 to SRAS2; AD and LRAS unchanged."}},{"g":{"k":"adas","ad":[0,-1],"sras":0,"lras":0,"alt":"AD shifts left from AD1 to AD2; SRAS and LRAS unchanged."}},{"g":{"k":"adas","ad":[0,1],"sras":0,"lras":0,"alt":"AD shifts right from AD1 to AD2; SRAS and LRAS unchanged."}}],"why":["Oil is a key input, so higher oil prices raise production costs and shift SRAS left: PL rises and real GDP falls.","Higher input prices reduce short-run supply; SRAS shifts left, not right.","An input price change shifts SRAS; this graph shows a change in spending.","Higher oil prices raise costs; nothing here increases spending."]},
    {"id":"m3.3-03","t":"3.3","d":2,"q":"Which of the following would shift the SRAS curve to the right?","c":["A decrease in nominal wages","An increase in government spending","An increase in the price level","An increase in business taxes"],"why":["Lower wages cut production costs, so firms supply more at every price level.","Government spending is part of AD; it shifts AD, not SRAS.","A price level change moves the economy along SRAS, not shifting it.","Higher business taxes raise costs and shift SRAS left."]},
    {"id":"m3.3-04","t":"3.3","d":2,"q":"Workers and firms come to expect higher inflation, and new wage contracts include larger raises. What happens in the short run?","c":["SRAS shifts left","SRAS shifts right","AD shifts left","LRAS shifts left"],"why":["Expected inflation raises nominal wages, a production cost, so SRAS shifts left.","Higher wage costs reduce short-run supply; SRAS shifts left, not right.","The change is in production costs, which affects supply, not spending.","Expectations change costs in the short run; LRAS depends on real resources and technology."]},
    {"id":"m3.3-05","t":"3.3","d":2,"g":{"k":"adas","ad":0,"sras":[0,-1],"lras":0,"alt":"AD-AS graph: SRAS shifts left from SRAS1 to SRAS2; AD and LRAS stay put."},"q":"Starting from long-run equilibrium, the economy experiences the change shown. What happens to the price level and real GDP in the short run?","c":["The price level increases and real GDP decreases","Both the price level and real GDP increase","Both the price level and real GDP decrease","The price level decreases and real GDP increases"],"why":["A leftward SRAS shift moves equilibrium up along AD: higher price level, lower output (stagflation).","Both rising happens when AD shifts right, not when SRAS shifts left.","Both falling happens when AD shifts left; this graph shows SRAS moving.","This is the result of SRAS shifting right, the opposite direction."]},
    {"id":"m3.3-06","t":"3.3","d":1,"q":"Which of the following would shift the SRAS curve to the left?","c":["New government regulations that raise firms' costs of compliance","A decrease in the price of energy","An increase in consumer spending","A decrease in the price level"],"why":["Regulations that add costs make each unit more expensive to produce, so SRAS shifts left.","Cheaper energy lowers costs and shifts SRAS right.","Consumer spending is part of AD, not SRAS.","A price level change moves along SRAS rather than shifting it."]},
    {"id":"m3.3-07","t":"3.3","d":3,"q":"The price of imported raw materials falls, and nothing else changes. What happens to the price level, real GDP and unemployment in the short run?","c":["Price level falls, real GDP rises, unemployment falls","Price level rises, real GDP rises, unemployment falls","Price level falls, real GDP falls, unemployment rises","Price level rises, real GDP falls, unemployment rises"],"why":["Cheaper inputs shift SRAS right: the economy slides down AD to a lower price level and higher output, so more people are employed.","A rising price level with more output comes from an AD increase, not lower costs.","This is an AD decrease; lower input costs raise output.","This is a negative supply shock, the opposite of cheaper inputs."]},
    {"id":"m3.3-08","t":"3.3","d":2,"q":"In the short run, the price level rises while nominal wages stay fixed by contracts. How do firms respond?","c":["They increase output, a movement up along the SRAS curve","SRAS shifts to the right","SRAS shifts to the left","LRAS shifts to the right"],"why":["Output prices rise while wage costs do not, so profit per unit rises and firms produce more along the existing SRAS.","A price level change is a movement along SRAS, not a shift.","Wages did not rise, so costs did not change; SRAS does not shift.","LRAS depends on resources and technology, not on a price level change."]},
    {"id":"m3.3-09","t":"3.3","d":3,"g":{"k":"adas","ad":0,"sras":[0,1],"lras":0,"alt":"AD-AS graph: SRAS shifts right from SRAS1 to SRAS2; AD and LRAS stay put. Output ends to the right of LRAS at a lower price level."},"q":"Which event could cause the change shown in the graph?","c":["A decrease in the price of oil","An increase in exports","An increase in nominal wages","A decrease in the price level"],"why":["Cheaper oil lowers production costs, shifting SRAS right: lower price level and higher real GDP.","More exports raise AD, not SRAS.","Higher wages raise costs and shift SRAS left.","A lower price level is a movement along SRAS, not a shift."]},
    {"id":"m3.3-10","t":"3.3","d":3,"q":"A major drought destroys a large share of a country's crops for one season. In the short run, which describes the economy?","c":["Higher price level and higher unemployment","Lower price level and higher unemployment","Higher price level and lower unemployment","Lower price level and lower unemployment"],"why":["A negative supply shock shifts SRAS left: prices rise and output falls, so unemployment rises (stagflation).","A lower price level with more unemployment comes from AD falling, not a supply shock.","Higher prices with lower unemployment come from AD rising.","This is a positive supply shock, the opposite of a drought."]},
    {"id":"m3.3-11","t":"3.3","d":2,"q":"The government gives firms a per-unit subsidy on everything they produce. What happens to SRAS?","c":["It shifts right, because the subsidy lowers firms' per-unit costs","It shifts left, because the subsidy raises government spending","It does not shift; AD shifts right instead","It does not shift; the economy moves along SRAS"],"why":["A per-unit subsidy works like a cost cut, the opposite of a business tax, so SRAS shifts right.","A subsidy lowers firms' costs; it does not reduce supply.","A per-unit subsidy to producers changes their costs, which is a supply-side determinant.","A change in costs shifts SRAS; only a price level change moves along it."]},
    {"id":"m3.4-01","t":"3.4","d":1,"q":"Why is the long-run aggregate supply curve vertical?","c":["In the long run, wages and prices fully adjust, so output depends on resources and technology, not the price level","In the long run, nominal wages never change","In the long run, aggregate demand cannot change","In the long run, a higher price level always raises real output"],"why":["Once input prices catch up with output prices, firms have no lasting reason to produce more at a higher price level, so output sits at full employment.","Sticky wages explain the upward slope of SRAS; in the long run they fully adjust.","AD can change in the long run; it just affects only the price level.","That describes an upward-sloping curve; in the long run the price level does not change real output."]},
    {"id":"m3.4-02","t":"3.4","d":1,"q":"When the economy produces at the output level on the LRAS curve, the unemployment rate equals which of the following?","c":["The natural rate of unemployment","Zero","The cyclical unemployment rate","A rate above the natural rate"],"why":["Full-employment output means only frictional and structural unemployment remain, which together are the natural rate.","Full employment still includes frictional and structural unemployment, so the rate is above zero.","At full employment cyclical unemployment is zero.","Unemployment above the natural rate means output is below LRAS (a recessionary gap)."]},
    {"id":"m3.4-03","t":"3.4","d":2,"q":"A new technology permanently raises how much each worker can produce. Which graph shows the change in full-employment output?","c":[{"g":{"k":"adas","lras":[0,1],"alt":"LRAS shifts right from LRAS1 to LRAS2."}},{"g":{"k":"adas","lras":[0,-1],"alt":"LRAS shifts left from LRAS1 to LRAS2."}},{"g":{"k":"adas","ad":[0,1],"sras":0,"lras":0,"alt":"AD shifts right from AD1 to AD2; SRAS and LRAS unchanged."}},{"g":{"k":"adas","ad":0,"sras":[0,1],"lras":0,"alt":"SRAS shifts right from SRAS1 to SRAS2; AD and LRAS unchanged."}}],"why":["Better technology raises the economy's productive capacity, so LRAS (full-employment output) shifts right.","Better technology raises capacity; LRAS shifts right, not left.","A change in spending does not change full-employment output, and LRAS does not move here.","This graph leaves LRAS in place, so full-employment output has not changed. Lasting productivity gains shift LRAS."]},
    {"id":"m3.4-04","t":"3.4","d":2,"q":"Which of the following would shift the LRAS curve to the left?","c":["An earthquake destroys a large part of the country's factories and roads","A decrease in aggregate demand","A one-time increase in nominal wages","An increase in the price level"],"why":["Losing capital reduces what the economy can produce at full employment, so LRAS shifts left.","A fall in AD lowers output only in the short run; it does not change capacity.","Nominal wage changes shift SRAS, not LRAS.","A price level change does not change full-employment output."]},
    {"id":"m3.4-05","t":"3.4","d":2,"q":"A country's production possibilities curve shifts outward. How is this shown in the AD-AS model?","c":["The LRAS curve shifts to the right","The AD curve shifts to the right","The LRAS curve shifts to the left","The economy moves along the SRAS curve"],"why":["Both the PPC and LRAS show productive capacity at full employment, so an outward PPC shift matches a rightward LRAS shift.","AD is about spending, not capacity.","An outward PPC shift means more capacity, so LRAS moves right, not left.","A movement along SRAS is a short-run change in output, not a change in capacity."]},
    {"id":"m3.4-06","t":"3.4","d":3,"g":{"k":"ppc","ppc":1,"x":"Consumer goods","y":"Capital goods","pts":[[40,40,"A"]],"alt":"PPC graph: point A lies inside the bowed-out production possibilities curve."},"q":"The economy produces at point A on the PPC shown. Where is the economy's short-run equilibrium on an AD-AS graph?","c":["To the left of LRAS, in a recessionary gap","On LRAS, in long-run equilibrium","To the right of LRAS, in an inflationary gap","Where LRAS has shifted left to meet current output"],"why":["A point inside the PPC means unused resources, so real GDP is below full-employment output: left of LRAS.","Long-run equilibrium matches a point on the PPC, not inside it.","Output beyond full employment would be shown outside the curve, and a point on the curve is full employment; neither is inside it.","Point A is inside an unchanged PPC, so capacity has not fallen; resources are just idle."]},
    {"id":"m3.4-07","t":"3.4","d":1,"q":"A change in which of the following would NOT shift the LRAS curve?","c":["The price level","The size of the labor force","The level of technology","The stock of physical capital"],"why":["The price level changes nothing about real resources or technology, so LRAS stays put.","More or fewer workers changes productive capacity, which shifts LRAS.","Technology changes how much can be produced, which shifts LRAS.","More or less capital changes capacity, which shifts LRAS."]},
    {"id":"m3.4-08","t":"3.4","d":2,"q":"A large wave of working-age immigrants joins a country's labor force. What is the long-run effect?","c":["LRAS shifts right","LRAS shifts left","Only AD shifts right; LRAS is unchanged","LRAS is unchanged because the price level rises"],"why":["More workers means more labor resources, so full-employment output rises.","Adding workers raises capacity; LRAS moves right, not left.","New residents also spend, but the lasting change is more labor, which raises capacity.","The price level does not determine LRAS."]},
    {"id":"m3.4-09","t":"3.4","d":3,"q":"An economy in long-run equilibrium has an unemployment rate of 5 percent. What does that 5 percent consist of?","c":["Frictional and structural unemployment only","Cyclical unemployment only","Frictional unemployment only","Frictional, structural and cyclical unemployment"],"why":["At full employment cyclical unemployment is zero, so the natural rate is frictional plus structural.","Cyclical unemployment is zero in long-run equilibrium.","Structural unemployment also exists at full employment.","Cyclical unemployment exists only when output is below full employment."]},
    {"id":"m3.4-10","t":"3.4","d":3,"g":{"k":"adas","ad":[0,1],"sras":[0,1],"lras":[0,1],"alt":"AD-AS graph: AD, SRAS and LRAS all shift right by the same amount; the new equilibrium sits on LRAS2 at the original price level."},"q":"The graph shows AD, SRAS and LRAS all shifting right. Compared with the starting point, which describes the new long-run equilibrium?","c":["Real GDP and full-employment output are higher, and the price level is unchanged","Real GDP is higher and the price level is higher","Real GDP is higher and the price level is lower","Real GDP is unchanged and the price level is higher"],"why":["Equal right shifts in all three curves raise output to the new full-employment level without changing the price level.","The price level would rise only if AD grew faster than supply.","The price level would fall only if supply grew faster than AD.","LRAS shifted right, so full-employment output, and real GDP with it, rose."]},
    {"id":"m3.4-11","t":"3.4","d":2,"q":"A country greatly expands access to job training and higher education. What is the expected long-run effect on aggregate supply?","c":["LRAS shifts right because human capital raises productivity","LRAS shifts left because students leave the labor force","Only SRAS shifts right; LRAS cannot change","LRAS does not shift because education is government spending"],"why":["More skilled workers produce more per hour, which raises full-employment output.","Any short pause in work is outweighed in the long run by higher productivity.","LRAS shifts whenever resources, technology or productivity change.","Spending on education also raises human capital, which shifts LRAS over time."]},
    {"id":"m3.5-01","t":"3.5","d":1,"g":{"k":"adas","ad":-1,"sras":0,"lras":0,"alt":"AD-AS graph: AD crosses SRAS to the left of LRAS."},"q":"What does the graph show?","c":["A recessionary (negative output) gap","An inflationary (positive output) gap","Long-run equilibrium","A rightward shift of LRAS"],"why":["AD and SRAS meet at output below full employment (left of LRAS), so there is a negative output gap.","An inflationary gap has equilibrium output to the right of LRAS.","Long-run equilibrium requires AD and SRAS to meet on LRAS.","No curve is shown shifting; the gap is the distance between current output and LRAS."]},
    {"id":"m3.5-02","t":"3.5","d":2,"g":{"k":"adas","ad":1,"sras":0,"lras":0,"alt":"AD-AS graph: AD crosses SRAS to the right of LRAS."},"q":"For the economy shown, how does the unemployment rate compare with the natural rate of unemployment?","c":["It is below the natural rate","It is above the natural rate","It equals the natural rate","It is zero"],"why":["Output is above full employment (an inflationary gap), so firms are using extra labor and unemployment is below the natural rate.","Unemployment above the natural rate goes with output below LRAS.","Unemployment equals the natural rate only when output is on LRAS.","Some frictional and structural unemployment remains even in a boom."]},
    {"id":"m3.5-03","t":"3.5","d":2,"q":"Which graph shows an economy in long-run equilibrium?","c":[{"g":{"k":"adas","ad":0,"sras":0,"lras":0,"alt":"AD, SRAS and LRAS all cross at one point."}},{"g":{"k":"adas","ad":-1,"sras":0,"lras":0,"alt":"AD crosses SRAS to the left of LRAS."}},{"g":{"k":"adas","ad":1,"sras":0,"lras":0,"alt":"AD crosses SRAS to the right of LRAS."}},{"g":{"k":"adas","ad":0,"sras":-1,"lras":0,"alt":"AD crosses a leftward-placed SRAS to the left of LRAS at a higher price level."}}],"why":["Long-run equilibrium is where AD and SRAS meet on LRAS.","Output is below full employment, a recessionary gap.","Output is above full employment, an inflationary gap.","Output is below full employment here, so it is a short-run equilibrium with a gap."]},
    {"id":"m3.5-04","t":"3.5","d":1,"q":"Which statement is true when an economy is in long-run equilibrium?","c":["AD and SRAS intersect on the LRAS curve, and unemployment equals the natural rate","AD and SRAS intersect to the right of LRAS, and unemployment is zero","AD and SRAS intersect to the left of LRAS, and there is no inflation","The price level must be at its lowest possible value"],"why":["Long-run equilibrium means output equals full-employment output, so only frictional and structural unemployment remain.","Output right of LRAS is an inflationary gap, and unemployment is never zero.","Output left of LRAS is a recessionary gap, not long-run equilibrium.","Long-run equilibrium can occur at any price level; it is about output being at Yf."]},
    {"id":"m3.5-05","t":"3.5","d":3,"q":"An economy is in a recessionary gap and the government takes no action. Which graph shows how the economy returns to long-run equilibrium?","c":[{"g":{"k":"adas","ad":-1,"sras":[0,1],"lras":0,"alt":"SRAS shifts right from SRAS1 to SRAS2 until it meets AD on LRAS at a lower price level."}},{"g":{"k":"adas","ad":-1,"sras":[0,-1],"lras":0,"alt":"SRAS shifts left from SRAS1 to SRAS2, moving output further left of LRAS."}},{"g":{"k":"adas","ad":[-1,0],"sras":0,"lras":0,"alt":"AD shifts right from AD1 to AD2, meeting SRAS on LRAS."}},{"g":{"k":"adas","ad":[-1,-2],"sras":0,"lras":0,"alt":"AD shifts further left from AD1 to AD2, moving output further below LRAS."}}],"why":["High unemployment pushes nominal wages down over time, shifting SRAS right until output is back at Yf at a lower price level.","Wages fall, not rise, in a recession; SRAS shifting left would deepen the gap.","Without policy nothing makes AD rise on its own; self-adjustment works through wages and SRAS.","This shows the recession getting worse, not the long-run adjustment."]},
    {"id":"m3.5-06","t":"3.5","d":3,"q":"An economy is in an inflationary gap and the government takes no action. Which graph shows how the economy returns to long-run equilibrium?","c":[{"g":{"k":"adas","ad":1,"sras":[0,-1],"lras":0,"alt":"SRAS shifts left from SRAS1 to SRAS2 until it meets AD on LRAS at a higher price level."}},{"g":{"k":"adas","ad":1,"sras":[0,1],"lras":0,"alt":"SRAS shifts right from SRAS1 to SRAS2, moving output further right of LRAS."}},{"g":{"k":"adas","ad":[1,0],"sras":0,"lras":0,"alt":"AD shifts left from AD1 to AD2, meeting SRAS on LRAS."}},{"g":{"k":"adas","ad":[1,2],"sras":0,"lras":0,"alt":"AD shifts further right from AD1 to AD2, moving output further past LRAS."}}],"why":["Low unemployment pushes nominal wages up, shifting SRAS left until output returns to Yf at an even higher price level.","Wages rise, not fall, in a boom; SRAS shifting right would widen the gap.","Without policy AD does not fall on its own; adjustment comes through wages and SRAS.","This shows the boom getting bigger, not the long-run adjustment."]},
    {"id":"m3.5-07","t":"3.5","d":2,"q":"The unemployment rate is 8 percent and the natural rate of unemployment is 5 percent. Which describes the economy?","c":["A recessionary gap: real GDP is below full-employment output","An inflationary gap: real GDP is above full-employment output","Long-run equilibrium with some structural unemployment","A recessionary gap: real GDP is above full-employment output"],"why":["Unemployment above the natural rate means there is cyclical unemployment, so output is below Yf.","An inflationary gap has unemployment below the natural rate.","Long-run equilibrium requires unemployment to equal the natural rate.","In a recessionary gap output is below Yf, not above it."]},
    {"id":"m3.5-08","t":"3.5","d":2,"q":"In a recessionary gap with no government policy, what happens in the long run?","c":["Nominal wages fall, SRAS shifts right, the price level falls and output returns to full employment","Nominal wages rise, SRAS shifts left, and output returns to full employment","AD shifts right on its own, and the price level rises","LRAS shifts left to meet the lower level of output"],"why":["Unemployment above the natural rate pushes wages down, lowering costs and shifting SRAS right back to Yf.","Wages rise in an inflationary gap, not a recession, and SRAS shifting left lowers output.","Self-adjustment works through wages and SRAS, not through AD.","A recession leaves resources idle but does not reduce capacity, so LRAS stays put."]},
    {"id":"m3.5-09","t":"3.5","d":3,"q":"An economy is in long-run equilibrium when AD increases. Compared with the starting point, which describes the short run and the long run?","c":["Short run: higher price level and higher real GDP. Long run: an even higher price level, with real GDP back at full employment","Short run: higher price level and higher real GDP. Long run: price level back to its start, real GDP stays higher","Short run: higher price level only. Long run: higher real GDP only","Short run: higher real GDP and lower price level. Long run: both back to their starting values"],"why":["AD moves the economy up SRAS first. Then wages rise, SRAS shifts left, and output returns to Yf at a higher price level.","In the long run output cannot stay above Yf, and the price level ends higher, not back where it started.","In the short run both PL and output rise; in the long run only PL is higher.","An AD increase raises the price level, and the long-run price level stays higher."]},
    {"id":"m3.5-10","t":"3.5","d":2,"g":{"k":"adas","ad":0,"sras":-1,"lras":0,"alt":"AD-AS graph: AD crosses SRAS to the left of LRAS, at a price level above the full-employment level."},"q":"Which describes the economy shown in the graph?","c":["A recessionary gap, with unemployment above the natural rate","An inflationary gap, with unemployment below the natural rate","Long-run equilibrium, with unemployment at the natural rate","A recessionary gap, with unemployment below the natural rate"],"why":["Short-run equilibrium output is left of LRAS, so output is below Yf and cyclical unemployment exists.","The price level is high, but output is below Yf; a gap is judged by output, not the price level.","AD and SRAS do not meet on LRAS, so this is not long-run equilibrium.","Output below full employment means unemployment above the natural rate, not below."]},
    {"id":"m3.5-11","t":"3.5","d":3,"q":"Real GDP is $1,050 billion and full-employment output is $1,000 billion. Which is true?","c":["There is a $50 billion inflationary gap, and unemployment is below the natural rate","There is a $50 billion recessionary gap, and unemployment is above the natural rate","There is a $50 billion inflationary gap, and unemployment is above the natural rate","The economy is in long-run equilibrium because the gap is small"],"why":["Output above Yf by $50 billion is a positive output gap, and producing beyond Yf pulls unemployment below the natural rate.","Output above full employment is an inflationary gap, not a recessionary one.","When output exceeds Yf, unemployment falls below the natural rate.","Any difference between actual and full-employment output is a gap, whatever its size."]},
    {"id":"m3.6-01","t":"3.6","d":1,"g":{"k":"adas","ad":[0,-1],"sras":0,"lras":0,"alt":"AD-AS graph: AD shifts left from AD1 to AD2 along an unchanged SRAS; LRAS stays put."},"q":"A stock market crash sharply reduces household wealth, shifting aggregate demand as shown. In the short run, what happens to the price level and real GDP?","c":["Both decrease","Both increase","Price level increases and real GDP decreases","Price level decreases and real GDP stays at full employment"],"why":["Lower wealth cuts consumption, so AD shifts left along SRAS: the new equilibrium has a lower PL and lower real GDP.","Both rise only when AD shifts right; a wealth loss reduces spending.","Higher PL with lower output is what a leftward SRAS shift (supply shock) causes, not a demand shock.","Output stays at Yf only in the long run or along a vertical LRAS; in the short run SRAS slopes up, so output falls too."]},
    {"id":"m3.6-02","t":"3.6","d":2,"g":{"k":"adas","ad":0,"sras":[0,-1],"lras":0,"alt":"AD-AS graph: SRAS shifts left from SRAS1 to SRAS2; AD and LRAS stay put."},"q":"Which event would most likely cause the shift shown in the graph?","c":["A sharp, economy-wide increase in the price of oil","An increase in government spending on defense","A decrease in nominal wages across the economy","A rise in labor productivity from new technology"],"why":["Oil is an input used almost everywhere, so higher oil prices raise production costs and shift SRAS left.","Government spending is a part of AD, so it would shift AD right, not SRAS.","Lower nominal wages cut production costs and shift SRAS right, the opposite direction.","Higher productivity lowers cost per unit and shifts SRAS right, not left."]},
    {"id":"m3.6-03","t":"3.6","d":1,"q":"Stagflation in the short run is best described as","c":["a rising price level together with falling real GDP and rising unemployment, caused by a negative supply shock","a rising price level together with rising real GDP, caused by an increase in aggregate demand","a falling price level together with falling real GDP, caused by a decrease in aggregate demand","a falling price level together with rising real GDP, caused by a positive supply shock"],"why":["When SRAS shifts left, PL rises while output falls and unemployment rises: inflation and stagnation at once.","Higher PL with higher output is demand-pull inflation, not stagflation; output is not stagnating.","Falling PL and falling output is a demand-side recession; there is no inflation, so it is not stagflation.","A positive supply shock is good news on both fronts: lower PL and higher output."]},
    {"id":"m3.6-04","t":"3.6","d":2,"q":"Foreign incomes rise and a country's exports increase sharply. Which graph shows the short-run effect on that country's economy, starting from full employment?","c":[{"g":{"k":"adas","lras":0,"ad":[0,1],"sras":0,"alt":"AD shifts right from AD1 to AD2; SRAS and LRAS unchanged."}},{"g":{"k":"adas","lras":0,"ad":[0,-1],"sras":0,"alt":"AD shifts left from AD1 to AD2; SRAS and LRAS unchanged."}},{"g":{"k":"adas","lras":0,"ad":0,"sras":[0,1],"alt":"SRAS shifts right from SRAS1 to SRAS2; AD and LRAS unchanged."}},{"g":{"k":"adas","lras":0,"ad":0,"sras":[0,-1],"alt":"SRAS shifts left from SRAS1 to SRAS2; AD and LRAS unchanged."}}],"why":["Net exports are part of AD (C + I + G + Xn), so more exports shift AD right, raising PL and real GDP.","This shows a decrease in AD; more exports add spending, so AD rises.","Exports are spending, not a production cost, so they shift AD, not SRAS.","A leftward SRAS shift comes from higher input costs, not from more foreign spending."]},
    {"id":"m3.6-05","t":"3.6","d":2,"q":"Energy prices fall sharply across the economy. In the short run, what happens to the price level and the unemployment rate?","c":["The price level falls and unemployment falls","The price level rises and unemployment rises","The price level falls and unemployment rises","The price level rises and unemployment falls"],"why":["Cheaper energy lowers production costs, so SRAS shifts right: PL falls and real GDP rises, so firms hire more and unemployment falls.","That is the result of a negative supply shock (higher energy prices), the opposite case.","PL falling with unemployment rising is a leftward AD shift; this is a supply shift to the right, which raises output.","PL rising with unemployment falling is a rightward AD shift; cheaper inputs lower PL."]},
    {"id":"m3.6-06","t":"3.6","d":3,"q":"In the same period, consumer spending rises sharply and a drought raises the cost of food and other raw materials. What is the short-run effect on the price level and real GDP?","c":["The price level increases; the change in real GDP is indeterminate","Both the price level and real GDP increase","The price level is indeterminate; real GDP decreases","The price level increases; real GDP decreases"],"why":["AD shifts right and SRAS shifts left. Both push PL up, but AD pushes output up while SRAS pushes it down, so the output change depends on which shift is bigger.","Real GDP rises only if the AD shift is larger; without sizes we cannot say.","Both shifts raise PL, so PL is certain; it is output that is uncertain.","Output falls only if the SRAS shift is larger; without sizes we cannot say."]},
    {"id":"m3.6-07","t":"3.6","d":3,"q":"Business investment falls because firms grow pessimistic, while at the same time nominal wages fall across the economy. What is the short-run effect?","c":["The price level decreases; the change in real GDP is indeterminate","The price level decreases and real GDP decreases","The price level is indeterminate; real GDP decreases","The price level is indeterminate; real GDP increases"],"why":["AD shifts left and SRAS shifts right. Both lower PL, but they push output in opposite directions, so the output change is indeterminate.","Output falls only if the AD shift is larger than the SRAS shift; the sizes are not given.","Both shifts pull PL down, so PL is the certain variable, not output.","Both shifts pull PL down; and output could rise or fall, so it is not certain either way."]},
    {"id":"m3.6-08","t":"3.6","d":3,"q":"Government spending increases at the same time as a technology breakthrough lowers production costs. What is the short-run effect on the price level and real GDP?","c":["Real GDP increases; the change in the price level is indeterminate","Both the price level and real GDP increase","The price level increases; the change in real GDP is indeterminate","Real GDP increases and the price level decreases"],"why":["AD shifts right and SRAS shifts right. Both raise output, but AD pushes PL up while SRAS pushes it down, so PL is indeterminate.","PL rises only if the AD shift is larger; that is not given.","Both shifts raise output, so output is certain; PL is the uncertain one.","PL falls only if the SRAS shift is larger; that is not given."]},
    {"id":"m3.6-09","t":"3.6","d":2,"g":{"k":"adas","ad":[0,1],"sras":0,"lras":0,"alt":"AD-AS graph: starting at full employment, AD shifts right from AD1 to AD2, so the new equilibrium is to the right of LRAS."},"q":"The economy starts at full employment and AD shifts as shown. Compared with the original equilibrium, the new short-run equilibrium has","c":["real GDP above full-employment output and unemployment below the natural rate","real GDP below full-employment output and unemployment above the natural rate","real GDP equal to full-employment output and a higher price level","real GDP above full-employment output and unemployment above the natural rate"],"why":["The new equilibrium sits right of LRAS: output above Yf, so unemployment is below its natural rate (an inflationary gap).","That describes a recessionary gap from a leftward AD shift.","Output returns to Yf only in the long run after SRAS adjusts; in the short run it is above Yf.","More output needs more workers, so unemployment falls, not rises."]},
    {"id":"m3.6-10","t":"3.6","d":2,"q":"A hurricane destroys many of a country's oil refineries and ports, raising costs for most firms. Which graph shows the short-run effect, starting from full employment?","c":[{"g":{"k":"adas","lras":0,"ad":0,"sras":[0,-1],"alt":"SRAS shifts left from SRAS1 to SRAS2; AD and LRAS unchanged."}},{"g":{"k":"adas","lras":0,"ad":[0,-1],"sras":0,"alt":"AD shifts left from AD1 to AD2; SRAS and LRAS unchanged."}},{"g":{"k":"adas","lras":0,"ad":0,"sras":[0,1],"alt":"SRAS shifts right from SRAS1 to SRAS2; AD and LRAS unchanged."}},{"g":{"k":"adas","lras":0,"ad":[0,1],"sras":0,"alt":"AD shifts right from AD1 to AD2; SRAS and LRAS unchanged."}}],"why":["Higher costs for most firms is a negative supply shock: SRAS shifts left, raising PL and lowering real GDP.","The story is about production costs, not spending; a leftward AD shift would also lower PL.","A rightward SRAS shift means costs fell; here costs rose.","Rebuilding may add spending later, but the immediate effect of higher costs is on SRAS."]},
    {"id":"m3.6-11","t":"3.6","d":1,"q":"Which of the following would shift the short-run aggregate supply curve to the right?","c":["A decrease in the price of imported raw materials","An increase in consumer optimism","An increase in business taxes on production","An increase in nominal wages"],"why":["Cheaper inputs lower firms' costs, so they supply more at every PL: SRAS shifts right.","Consumer optimism raises consumption, which shifts AD, not SRAS.","Higher business taxes raise costs and shift SRAS left.","Higher nominal wages raise costs and shift SRAS left."]},
    {"id":"m3.7-01","t":"3.7","d":1,"g":{"k":"adas","ad":-1,"sras":0,"lras":0,"alt":"AD-AS graph: AD and SRAS meet to the left of LRAS, a recessionary gap."},"q":"The economy is at the short-run equilibrium shown. If wages are flexible and there is no policy action, what happens in the long run?","c":["Nominal wages fall, SRAS shifts right, and real GDP returns to full employment at a lower price level","Nominal wages rise, SRAS shifts left, and real GDP returns to full employment at a higher price level","AD shifts right on its own, and real GDP returns to full employment at a higher price level","LRAS shifts left to meet the current output, so the gap disappears"],"why":["Output is below Yf, so unemployment is high and nominal wages fall over time. Lower costs shift SRAS right until output is back at Yf, at a lower PL.","Wages rise in an inflationary gap, not when unemployment is above its natural rate.","Self-adjustment works through wages and SRAS; AD does not shift back on its own without a change in spending or policy.","LRAS depends on resources and technology, not on a temporary drop in demand."]},
    {"id":"m3.7-02","t":"3.7","d":2,"q":"Which graph shows how an economy with an inflationary gap returns to long-run equilibrium if there is no policy action?","c":[{"g":{"k":"adas","lras":0,"ad":1,"sras":[0,-1],"alt":"AD sits right of the original equilibrium; SRAS shifts left from SRAS1 to SRAS2, so the new equilibrium is on LRAS at a higher price level."}},{"g":{"k":"adas","lras":0,"ad":1,"sras":[0,1],"alt":"AD sits right of the original equilibrium; SRAS shifts right from SRAS1 to SRAS2, moving output further right of LRAS."}},{"g":{"k":"adas","lras":0,"ad":[1,0],"sras":0,"alt":"AD shifts left from AD1 to AD2, so the new equilibrium is on LRAS at a lower price level."}},{"g":{"k":"adas","lras":[0,0.5],"ad":1,"sras":0,"alt":"AD and SRAS unchanged; LRAS shifts right from LRAS1 to LRAS2 to meet the current output."}}],"why":["Output above Yf means a tight labor market, so nominal wages rise and SRAS shifts left until output is back at Yf, at a higher PL.","SRAS shifts right only when wages fall, which happens in a recessionary gap.","A leftward AD shift is what contractionary policy does; with no policy, the adjustment comes through SRAS.","LRAS does not move just because demand is high; it depends on resources and technology."]},
    {"id":"m3.7-03","t":"3.7","d":1,"q":"An economy self-adjusts from a recessionary gap. Compared with the short-run equilibrium during the gap, the new long-run equilibrium has","c":["a lower price level and higher real GDP","a higher price level and higher real GDP","a lower price level and the same real GDP","a higher price level and lower real GDP"],"why":["SRAS shifts right along the unchanged AD: PL falls and output rises back to Yf.","A higher PL with higher output would be a rightward AD shift, not a rightward SRAS shift.","During the gap output was below Yf, so returning to Yf means output rises.","This is the result of SRAS shifting left, which happens in an inflationary gap."]},
    {"id":"m3.7-04","t":"3.7","d":2,"q":"In an inflationary gap with no policy action, why does the SRAS curve eventually shift to the left?","c":["Unemployment is below its natural rate, so workers win higher nominal wages, raising firms' costs","Unemployment is above its natural rate, so nominal wages fall, lowering firms' costs","The higher price level reduces real wealth, so consumers spend less","Firms run out of capital, so the economy's full-employment output falls"],"why":["A tight labor market pushes nominal wages and other input prices up as contracts renew, so SRAS shifts left.","In an inflationary gap unemployment is below, not above, its natural rate; and falling costs would shift SRAS right.","The wealth effect is a movement along AD, not a reason for SRAS to shift.","Full-employment output (LRAS) does not shrink because of an inflationary gap."]},
    {"id":"m3.7-05","t":"3.7","d":2,"g":{"k":"adas","ad":[0,1],"sras":0,"lras":0,"alt":"AD-AS graph: starting at full employment, AD shifts right from AD1 to AD2; LRAS stays put."},"q":"Starting from long-run equilibrium, AD shifts as shown. If no policy is used and wages are flexible, how will the final long-run equilibrium compare with the original one before AD shifted?","c":["A higher price level and the same real GDP","The same price level and higher real GDP","A higher price level and higher real GDP","The same price level and the same real GDP"],"why":["Wages rise and SRAS shifts left until output is back at Yf; the only lasting change from more demand is a higher PL.","In the long run output is fixed at Yf by LRAS, so extra demand cannot keep output above it.","Output is above Yf only in the short run; the SRAS shift brings it back to Yf.","AD is still higher than before, so the PL ends higher even though output returns to Yf."]},
    {"id":"m3.7-06","t":"3.7","d":2,"q":"An economy has an unemployment rate above its natural rate. If the government takes no action and wages are flexible, what happens to unemployment in the long run?","c":["It falls back to the natural rate as falling wages shift SRAS right","It stays above the natural rate permanently","It falls to zero as output rises above full employment","It rises further as falling wages reduce spending"],"why":["Self-adjustment brings output back to Yf, which by definition means unemployment returns to the natural rate.","With flexible wages the gap closes on its own; it may be slow, but it is not permanent in the model.","Full employment still has frictional and structural unemployment; the natural rate is not zero.","In the AD-AS model, falling wages lower costs and raise output, so unemployment falls."]},
    {"id":"m3.7-07","t":"3.7","d":3,"q":"Many economists argue that self-adjustment out of a recessionary gap can take a long time. Which reason best supports this view?","c":["Nominal wages are sticky downward because of contracts, minimum wages and worker resistance to pay cuts","Nominal wages rise quickly in a recession, so SRAS shifts the wrong way","The LRAS curve shifts left during every recession","Tax revenues rise during recessions, which slows spending"],"why":["Self-adjustment needs nominal wages to fall so SRAS shifts right; if wages fall slowly, the gap lingers.","Wages do not rise quickly when unemployment is high; the problem is they do not fall quickly.","LRAS is set by resources and technology; it does not shift left in every recession.","Tax revenues fall, not rise, in a recession."]},
    {"id":"m3.7-08","t":"3.7","d":2,"g":{"k":"adas","ad":1,"sras":[0,-1],"lras":0,"alt":"AD-AS graph: AD is to the right; SRAS shifts left from SRAS1 to SRAS2, moving equilibrium back to LRAS at a higher price level."},"q":"The graph shows the SRAS curve shifting from SRAS1 to SRAS2 with no policy action. What most likely caused this shift?","c":["Output was above full employment, so nominal wages rose","Output was below full employment, so nominal wages fell","The government raised spending to close a recessionary gap","A technology improvement lowered firms' costs"],"why":["The first equilibrium was right of LRAS (an inflationary gap); rising wages pushed SRAS left until output returned to Yf.","Falling wages lower costs and shift SRAS right, not left.","Government spending shifts AD, not SRAS, and the original output was above Yf, not below it.","Lower costs would shift SRAS right."]},
    {"id":"m3.7-09","t":"3.7","d":3,"q":"A one-time negative supply shock causes stagflation. If there is no policy response and input prices are flexible, what happens in the long run?","c":["High unemployment pushes wages and input prices down, SRAS shifts back right, and PL and real GDP return to their original levels","SRAS keeps shifting left, so stagflation becomes permanent","AD shifts left on its own until real GDP returns to full employment","LRAS shifts left to meet the new lower output"],"why":["Output below Yf means high unemployment, so wages and input prices fall over time; SRAS shifts back right to the original long-run equilibrium.","With a one-time shock and flexible input prices, the shift reverses; it does not keep worsening.","AD does not move on its own; and shifting AD left would lower output further, not raise it.","A one-time cost shock does not change long-run resources or technology, so LRAS stays at Yf."]},
    {"id":"m3.7-10","t":"3.7","d":1,"q":"An economy is in long-run equilibrium when","c":["AD, SRAS and LRAS all intersect at the same point","AD intersects SRAS anywhere to the right of LRAS","SRAS intersects LRAS at any price level","AD intersects LRAS above the SRAS curve"],"why":["Long-run equilibrium means the short-run equilibrium (AD meets SRAS) is at full-employment output, on LRAS.","To the right of LRAS is an inflationary gap, a short-run equilibrium only.","AD must pass through the same point, or the economy is not in equilibrium there.","If AD meets LRAS at a point off SRAS, that point is not a short-run equilibrium."]},
    {"id":"m3.7-11","t":"3.7","d":2,"q":"Which graph shows an economy closing a recessionary gap through long-run self-adjustment?","c":[{"g":{"k":"adas","lras":0,"ad":-1,"sras":[0,1],"alt":"AD sits left of the original equilibrium; SRAS shifts right from SRAS1 to SRAS2, so the new equilibrium is on LRAS at a lower price level."}},{"g":{"k":"adas","lras":0,"ad":-1,"sras":[0,-1],"alt":"AD sits left of the original equilibrium; SRAS shifts left from SRAS1 to SRAS2, moving output further left of LRAS."}},{"g":{"k":"adas","lras":0,"ad":[-1,0],"sras":0,"alt":"AD shifts right from AD1 to AD2, so the new equilibrium is on LRAS at a higher price level."}},{"g":{"k":"adas","lras":[0,-0.5],"ad":-1,"sras":0,"alt":"AD and SRAS unchanged; LRAS shifts left from LRAS1 to LRAS2 to meet the current output."}}],"why":["Output below Yf means high unemployment, so nominal wages fall and SRAS shifts right until output is back at Yf.","SRAS shifts left when wages rise, which happens in an inflationary gap; here it would deepen the recession.","A rightward AD shift is what expansionary policy does; self-adjustment works through SRAS.","LRAS does not move just because demand is weak."]},
    {"id":"m3.8-01","t":"3.8","d":1,"q":"Which fiscal policy is appropriate for closing a recessionary gap?","c":["Increase government spending or decrease taxes","Decrease government spending or increase taxes","Decrease transfer payments to shrink the budget deficit","Lower the interest rate the central bank pays on reserves"],"why":["Expansionary fiscal policy raises AD, pushing output up toward Yf.","That is contractionary policy; it shifts AD left and deepens the recession.","Cutting transfers lowers disposable income and consumption, shifting AD left and deepening the recession.","Interest rates on reserves are a tool of monetary policy, not fiscal policy."]},
    {"id":"m3.8-02","t":"3.8","d":1,"q":"An economy is producing above full-employment output and inflation is rising. Which discretionary fiscal policy would be appropriate?","c":["Decrease government spending","Decrease personal income taxes","Increase transfer payments","Increase government purchases of military equipment"],"why":["An inflationary gap calls for contractionary policy; cutting G shifts AD left, lowering PL and output.","A tax cut raises disposable income and consumption, shifting AD right and making inflation worse.","More transfers raise disposable income and spending, which is expansionary.","More G of any kind adds to AD, which is expansionary."]},
    {"id":"m3.8-03","t":"3.8","d":2,"q":"Real GDP is $120 billion below full-employment output and the MPC is 0.75. Assuming no crowding out, by how much should government spending change to close the gap?","c":["Increase by $30 billion","Increase by $120 billion","Increase by $90 billion","Increase by $40 billion"],"why":["The spending multiplier is 1/MPS = 1/0.25 = 4, so $120 billion ÷ 4 = $30 billion of new G.","This ignores the multiplier; each dollar of G creates more than a dollar of GDP.","This multiplies the gap by the MPC instead of dividing by the multiplier.","This uses the tax multiplier (3); a change in G uses the spending multiplier (4)."]},
    {"id":"m3.8-04","t":"3.8","d":2,"q":"Real GDP is $120 billion below full-employment output and the MPC is 0.75. Using only a change in taxes, what change is needed to close the gap?","c":["Decrease taxes by $40 billion","Decrease taxes by $30 billion","Increase taxes by $40 billion","Decrease taxes by $160 billion"],"why":["The tax multiplier is -MPC/MPS = -0.75/0.25 = -3, so a $40 billion tax cut raises GDP by $120 billion.","This uses the spending multiplier (4); taxes have a smaller multiplier because part of a tax cut is saved.","A recessionary gap needs AD to rise, so taxes must fall, not rise.","This divides the gap by the MPC (120 ÷ 0.75) instead of by the tax multiplier."]},
    {"id":"m3.8-05","t":"3.8","d":3,"q":"Real GDP is $90 billion above full-employment output and the MPC is 0.75. Which change in government spending would close the gap?","c":["Decrease by $22.5 billion","Decrease by $30 billion","Increase by $22.5 billion","Decrease by $90 billion"],"why":["An inflationary gap needs AD to fall. The spending multiplier is 1/0.25 = 4, so $90 billion ÷ 4 = $22.5 billion cut in G.","This uses the tax multiplier (3); a change in G uses the spending multiplier (4).","Increasing G would widen an inflationary gap, not close it.","This ignores the multiplier effect."]},
    {"id":"m3.8-06","t":"3.8","d":2,"g":{"k":"adas","ad":[-1,0],"sras":0,"lras":0,"alt":"AD-AS graph: AD shifts right from AD1, left of LRAS, to AD2, so the new equilibrium is on LRAS at a higher price level."},"q":"The graph shows the effect of a discretionary fiscal policy action. Which action could have caused it?","c":["An increase in government spending on highways","An increase in personal income tax rates","A decrease in unemployment benefits","A decrease in nominal wages across the economy"],"why":["AD shifts right to close a recessionary gap; more government purchases add directly to AD.","Higher taxes cut disposable income and shift AD left.","Cutting transfers lowers disposable income and shifts AD left.","Lower wages shift SRAS, not AD, and wage changes are not fiscal policy."]},
    {"id":"m3.8-07","t":"3.8","d":2,"q":"An economy has an inflationary gap. Which graph shows the correct discretionary fiscal policy closing the gap?","c":[{"g":{"k":"adas","lras":0,"ad":[1,0],"sras":0,"alt":"AD shifts left from AD1, right of LRAS, to AD2, so the new equilibrium is on LRAS at a lower price level."}},{"g":{"k":"adas","lras":0,"ad":[1,2],"sras":0,"alt":"AD shifts right from AD1 to AD2, moving output further right of LRAS."}},{"g":{"k":"adas","lras":0,"ad":[-1,0],"sras":0,"alt":"AD shifts right from AD1, left of LRAS, to AD2 on LRAS at a higher price level."}},{"g":{"k":"adas","lras":0,"ad":1,"sras":[0,-1],"alt":"AD unchanged right of the original point; SRAS shifts left from SRAS1 to SRAS2, reaching LRAS at a higher price level."}}],"why":["Contractionary fiscal policy (less G or higher taxes) shifts AD left, so output falls to Yf and PL falls.","Shifting AD further right is expansionary policy, which widens the inflationary gap.","This starts from a recessionary gap, not an inflationary one.","This is long-run self-adjustment through rising wages, not fiscal policy."]},
    {"id":"m3.8-08","t":"3.8","d":2,"q":"The government's budget is balanced. It then cuts taxes and raises spending to fight a recession. Other things equal, what happens to the budget?","c":["It moves into deficit","It moves into surplus","It stays balanced because the higher GDP pays for the policy automatically","It stays balanced because spending rises and taxes fall by the same amount"],"why":["Lower tax revenue plus higher spending means the government spends more than it collects: a deficit.","A surplus results from contractionary policy (higher taxes or lower spending).","Higher GDP brings back some tax revenue, but not enough in the AP model to keep the budget balanced.","Raising spending and cutting taxes both widen the gap between spending and revenue; they do not cancel."]},
    {"id":"m3.8-09","t":"3.8","d":1,"q":"Which is a main reason discretionary fiscal policy may take effect after a recession is already over?","c":["It takes time to recognize the problem, pass a law and put the spending or tax change into effect","Fiscal policy changes the money supply, which takes years to adjust","Fiscal policy has no multiplier effect in the short run","Tax changes are made by the central bank, which meets only a few times a year"],"why":["Recognition, legislative and implementation lags can delay fiscal policy until the economy has already recovered.","The money supply is the tool of monetary policy, not fiscal policy.","Changes in G and taxes do have multiplier effects in the short run.","Taxes and spending are set by the legislature and executive, not the central bank."]},
    {"id":"m3.8-10","t":"3.8","d":3,"q":"The MPC is 0.75. The government increases spending by $40 billion and pays for it by raising taxes by $40 billion. What is the maximum change in real GDP?","c":["Increase of $40 billion","No change","Increase of $160 billion","Increase of $120 billion"],"why":["The spending change adds 4 × 40 = $160 billion and the tax change subtracts 3 × 40 = $120 billion, so GDP rises by $40 billion (balanced-budget multiplier of 1).","The two changes do not cancel because the tax multiplier is smaller than the spending multiplier.","This counts only the spending increase and ignores the tax increase.","This counts only the tax effect, with the wrong sign."]},
    {"id":"m3.8-11","t":"3.8","d":2,"q":"The MPC is 0.8. Which policy would increase aggregate demand by the largest amount?","c":["Increase government purchases by $10 billion","Decrease taxes by $10 billion","Increase transfer payments by $10 billion","Increase government purchases by $10 billion and taxes by $10 billion"],"why":["Purchases count fully in the first round: 5 × 10 = $50 billion.","A tax cut is partly saved first: 4 × 10 = $40 billion.","Transfers work like a tax cut, since households save part: 4 × 10 = $40 billion.","A balanced increase raises GDP only by the amount of G: 50 - 40 = $10 billion."]},
    {"id":"m3.8-12","t":"3.8","d":2,"q":"Why is the tax multiplier smaller in absolute value than the government spending multiplier?","c":["Households save part of a tax cut before any of it is spent, while government purchases are spent in full right away","Taxes affect SRAS while government spending affects AD","Tax cuts are always smaller than spending increases","The tax multiplier uses the MPS in the numerator instead of the MPC"],"why":["A tax cut first raises disposable income, and only the MPC share is spent, so the first round is smaller.","In AP Macro, both taxes and government spending shift AD.","The multiplier compares effects per dollar; it does not depend on the size of the change.","The tax multiplier is -MPC/MPS; the MPC, not the MPS, is in the numerator."]},
    {"id":"m3.9-01","t":"3.9","d":1,"q":"Which of the following is an automatic stabilizer?","c":["Unemployment insurance benefits","A highway-building program passed during a recession","A one-time tax rebate approved by the legislature","The central bank lowering its policy interest rate"],"why":["Benefits rise on their own when people lose jobs, with no new law, cushioning the drop in spending.","A new program passed by the legislature is discretionary fiscal policy.","A rebate that needs a vote is discretionary, not automatic.","Interest rate changes are monetary policy, not fiscal stabilizers."]},
    {"id":"m3.9-02","t":"3.9","d":1,"q":"What makes automatic stabilizers different from discretionary fiscal policy?","c":["They change taxes and transfers over the business cycle without any new legislation","They are decided by the central bank instead of the legislature","They shift the LRAS curve instead of the AD curve","They take effect only after the legislature votes during each recession"],"why":["Built into existing tax and transfer laws, they respond to changes in income automatically.","They are part of fiscal policy (taxes and transfers), not central bank decisions.","They dampen swings in AD; they do not change long-run capacity.","Needing a vote each time is exactly what makes a policy discretionary."]},
    {"id":"m3.9-03","t":"3.9","d":2,"q":"As an economy enters a recession, which change happens automatically under existing law?","c":["Tax revenue falls and transfer payments rise, so the budget deficit grows","Tax revenue rises and transfer payments fall, so the budget deficit shrinks","Tax revenue and transfer payments both fall, so the budget stays balanced","Tax rates are raised to keep revenue steady"],"why":["Lower incomes mean less tax collected, and more people qualify for aid, so spending rises: the deficit grows.","That is what happens in an expansion, when incomes rise.","Transfers such as unemployment benefits rise in a recession, not fall.","Changing tax rates needs new legislation, which is not automatic."]},
    {"id":"m3.9-04","t":"3.9","d":2,"q":"During a strong economic expansion, how do automatic stabilizers affect aggregate demand?","c":["Tax revenue rises and transfers fall, which slows the growth of AD","Tax revenue falls and transfers rise, which speeds up the growth of AD","They have no effect, because they only work in recessions","They shift SRAS left, which lowers output"],"why":["Rising incomes push up tax collections and fewer people need transfers, so disposable income grows more slowly, damping AD.","That is the recession pattern; in an expansion it reverses.","Stabilizers work in both directions, slowing booms as well as cushioning busts.","They work through disposable income and AD, not through production costs."]},
    {"id":"m3.9-05","t":"3.9","d":2,"q":"Why does a progressive income tax act as an automatic stabilizer?","c":["As incomes fall, the share taken in taxes falls, so disposable income falls by less than income","As incomes fall, tax rates are raised by law to keep revenue steady","Everyone pays the same dollar amount, so taxes do not change with the business cycle","It increases the money supply when incomes fall"],"why":["Under rising marginal rates, lower incomes face lower average tax rates, cushioning the drop in spending.","No new law is needed; the brackets already exist. Raising rates in a recession would make it worse.","A fixed dollar tax is a lump-sum tax, which does not stabilize anything.","Taxes are fiscal policy; they do not change the money supply."]},
    {"id":"m3.9-06","t":"3.9","d":2,"g":{"k":"adas","ad":[0,-1],"sras":0,"lras":0,"alt":"AD-AS graph: AD shifts left from AD1 to AD2 along an unchanged SRAS; LRAS stays put."},"q":"The graph shows the effect of a fall in business investment in an economy with no automatic stabilizers. If the same fall happened in an economy with strong automatic stabilizers, AD would","c":["shift left by a smaller amount, so real GDP falls less","shift left by a larger amount, so real GDP falls more","shift right, so real GDP rises above full employment","shift left by the same amount, because stabilizers only move SRAS"],"why":["Falling tax payments and rising transfers prop up disposable income, so consumption falls less and AD shifts left less.","Stabilizers cushion a downturn; they do not make it worse.","Stabilizers soften the drop; they do not reverse it or push output above Yf.","Stabilizers work through taxes and transfers, which affect AD, not SRAS."]},
    {"id":"m3.9-07","t":"3.9","d":3,"g":{"k":"adas","ad":1,"sras":0,"lras":0,"alt":"AD-AS graph: AD and SRAS meet to the right of LRAS, an inflationary gap."},"q":"The economy is at the short-run equilibrium shown and the legislature passes no new laws. Which response comes from automatic stabilizers?","c":["Tax collections rise and transfer payments fall, slowing the growth of spending","Lawmakers raise income tax rates to cool the economy","Unemployment benefit payments rise, adding to spending","Nominal wages rise, shifting SRAS to the left"],"why":["Output is above Yf, so incomes are high: existing tax laws collect more and fewer people draw benefits, damping AD.","Passing a rate increase is discretionary policy, which needs new legislation.","In an inflationary gap unemployment is low, so benefit payments fall, not rise.","Rising wages are long-run self-adjustment, not a fiscal stabilizer."]},
    {"id":"m3.9-08","t":"3.9","d":2,"q":"Which statement about automatic stabilizers is most accurate?","c":["They reduce the size of business-cycle swings but do not eliminate recessions or inflationary gaps","They eliminate recessions completely, so discretionary policy is never needed","They make recessions deeper by raising taxes when incomes fall","They work only when the legislature declares an emergency"],"why":["Stabilizers soften shifts in AD but only partly offset them, so gaps can still open.","They only cushion swings; large shocks can still cause serious recessions.","Under a progressive tax, tax payments fall when incomes fall, which cushions the recession.","They work automatically through existing law, with no declaration needed."]},
    {"id":"m3.9-09","t":"3.9","d":2,"q":"Which change would make a country's automatic stabilizers weaker?","c":["Replacing the progressive income tax with a lump-sum tax that is the same dollar amount for every household","Making the income tax more progressive","Expanding eligibility for unemployment insurance","Increasing food assistance that grows when household income falls"],"why":["A lump-sum tax does not change with income, so tax payments no longer fall in a recession or rise in a boom.","More progressive taxes make revenue respond more to income, strengthening the stabilizer.","Wider eligibility means transfers rise more in a downturn, a stronger stabilizer.","Aid that rises as income falls is itself an automatic stabilizer."]},
    {"id":"m3.9-10","t":"3.9","d":3,"q":"A country's budget deficit grows sharply during a recession even though the legislature did not change any tax or spending laws. What best explains this?","c":["Automatic stabilizers: tax revenue fell and transfer payments rose as incomes fell","Discretionary fiscal policy: the government chose to cut tax rates","The central bank bought government bonds, which raised the deficit","Real GDP rose, which increased government spending on interest"],"why":["With no new laws, the deficit grows because existing taxes collect less and existing programs pay out more in a downturn.","Cutting rates would require a new law, which the question rules out.","Central bank bond purchases are monetary policy and do not set the government's budget.","Real GDP falls in a recession, not rises."]},
    {"id":"m3.9-11","t":"3.9","d":2,"q":"What is one advantage of automatic stabilizers compared with discretionary fiscal policy?","c":["They avoid the recognition and legislative lags because they respond as soon as incomes change","They always balance the government budget each year","They permanently increase full-employment output","They do not affect aggregate demand, so they cannot cause inflation"],"why":["No one has to spot the problem or pass a law; tax payments and transfers change as soon as incomes change.","They push the budget toward deficit in recessions and surplus in booms, not balance each year.","They smooth short-run AD; they do not raise long-run capacity.","They work by changing disposable income and AD; that is how they stabilize."]}
  ];
  const FRQS = [
    {"id":"frq1-1","unit":1,"title":"Comparative advantage and trade","intro":"Norland and Sudia each have the same number of workers. In one day, Norland can produce either 60 bushels of wheat or 30 bolts of cloth. Sudia can produce either 20 bushels of wheat or 20 bolts of cloth. Each country has constant opportunity costs.","parts":[{"ask":"(a) Which country has the absolute advantage in producing wheat? Explain.","pts":["1 point: Norland, because with the same resources it can produce more wheat (60 bushels) than Sudia (20 bushels)."]},{"ask":"(b) Calculate Sudia's opportunity cost of producing 1 bolt of cloth.","pts":["1 point: 1 bushel of wheat (20 wheat ÷ 20 cloth)."]},{"ask":"(c) Which country has the comparative advantage in producing cloth? Explain using opportunity costs.","pts":["1 point: Sudia, because a bolt of cloth costs Sudia 1 bushel of wheat but costs Norland 2 bushels of wheat (60 ÷ 30)."]},{"ask":"(d) If the two countries specialize based on comparative advantage, identify a term of trade (bushels of wheat per bolt of cloth) that would benefit both countries, and explain why.","pts":["1 point: Any term between 1 and 2 bushels of wheat per bolt of cloth, for example 1 bolt of cloth for 1.5 bushels of wheat.","1 point: Explains that Sudia gets more than the 1 bushel it gives up to make a bolt of cloth, and Norland pays less than the 2 bushels it would give up to make a bolt itself."]},{"ask":"(e) Norland is currently producing 30 bushels of wheat and 10 bolts of cloth. Is this combination inside, on or outside Norland's production possibilities curve? Explain what it means.","pts":["1 point: Inside the PPC (making 30 wheat uses half of Norland's resources, which could still make 15 cloth, more than 10).","1 point: Explains that some of Norland's resources are unemployed or used inefficiently, so it could produce more of one good without giving up any of the other."],"model":{"k":"ppc","ppc":[[0.75,0.375]],"line":true,"x":"Wheat","y":"Cloth","pts":[[30,10,"N"]],"alt":"Norland's straight-line PPC from 30 bolts of cloth to 60 bushels of wheat, with point N (30 wheat, 10 cloth) inside the line."}}]},
    {"id":"frq2-1","unit":2,"title":"Measuring unemployment, output and inflation","intro":"Country Z has an adult population of 50 million. Of these, 28.5 million people are employed and 1.5 million are unemployed and actively looking for work. The rest are not in the labor force.","parts":[{"ask":"(a) Calculate the unemployment rate in Country Z. Show your work.","pts":["1 point: unemployment rate = 1.5 ÷ (28.5 + 1.5) × 100 = 1.5 ÷ 30 × 100 = 5%."]},{"ask":"(b) Calculate the labor force participation rate in Country Z. Show your work.","pts":["1 point: labor force participation rate = 30 ÷ 50 × 100 = 60%."]},{"ask":"(c) A typist loses her job because companies now use voice-to-text software, and she lacks the skills for the jobs that are open. Identify the type of unemployment she experiences.","pts":["1 point: structural unemployment."]},{"ask":"(d) Country Z's nominal GDP this year is $3,300 billion and its GDP deflator is 110. Calculate real GDP. Show your work.","pts":["1 point: real GDP = 3,300 ÷ 110 × 100 = $3,000 billion."]},{"ask":"(e) Suppose inflation turns out to be much higher than people expected. Identify one group that is hurt, and explain why.","pts":["1 point: identifies a group hurt, such as lenders who made fixed-rate loans, savers, or people on fixed nominal incomes.","1 point: explains that the money they receive buys less than expected; for lenders, the real interest rate is lower than planned because real rate = nominal rate - inflation."]}]},
    {"id":"frq3-1","unit":3,"title":"Recessionary gap and the multiplier","intro":"Assume the economy of Country Z is in short-run equilibrium with real GDP $100 billion below full-employment output. The marginal propensity to consume is 0.8.","parts":[{"ask":"(a) Draw a correctly labeled AD-AS graph showing the current short-run equilibrium. Label the current price level PL1, current output Y1 and full-employment output Yf.","pts":["1 point: correctly labeled axes (PL on the vertical axis, real GDP on the horizontal axis) with a downward-sloping AD, an upward-sloping SRAS and a vertical LRAS at Yf.","1 point: equilibrium where AD meets SRAS, with Y1 to the left of Yf and PL1 shown on the vertical axis."],"model":{"k":"adas","ad":-1,"sras":0,"lras":0,"alt":"AD-AS graph: AD crosses SRAS at Y1, to the left of the vertical LRAS at Yf."}},{"ask":"(b) Is the current unemployment rate above, below or equal to the natural rate of unemployment? Explain.","pts":["1 point: above the natural rate, because real GDP is below full-employment output, so there is cyclical unemployment."]},{"ask":"(c) Calculate the spending multiplier. Show your work.","pts":["1 point: 5, because MPS = 1 - 0.8 = 0.2 and 1/0.2 = 5."]},{"ask":"(d) Calculate the minimum increase in government spending that would close the gap. Show your work.","pts":["1 point: $20 billion, because $100 billion ÷ 5 = $20 billion (or a correct answer consistent with the multiplier in part (c))."]},{"ask":"(e) If the government takes no action, what will happen to nominal wages and to SRAS in the long run?","pts":["1 point: nominal wages fall and SRAS shifts right, returning output to Yf at a lower price level."]}]},
    {"id":"frq3-2","unit":3,"title":"Inflationary gap, fiscal policy and self-adjustment","intro":"Assume the economy of Country Z is in short-run equilibrium with real GDP above full-employment output. The government has a progressive income tax and an unemployment insurance program.","parts":[{"ask":"(a) Draw a correctly labeled AD-AS graph showing the current short-run equilibrium. Label the equilibrium price level PL1 and output Y1, and label full-employment output Yf.","pts":["1 point: correctly labeled axes (PL and real GDP) with downward-sloping AD, upward-sloping SRAS and vertical LRAS at Yf.","1 point: equilibrium PL1 and Y1 shown where AD meets SRAS, with Y1 to the right of Yf."],"model":{"k":"adas","ad":1,"sras":0,"lras":0,"alt":"AD-AS graph: AD and SRAS meet to the right of a vertical LRAS, an inflationary gap."}},{"ask":"(b) Identify one discretionary fiscal policy action the government could take to return the economy to full employment.","pts":["1 point: decrease government spending OR increase taxes (or decrease transfer payments)."]},{"ask":"(c) On your graph from part (a), show the effect of the policy you identified in part (b). What happens to the price level and real GDP?","pts":["1 point: AD shifts left, and the price level and real GDP both decrease (output moves toward Yf)."],"model":{"k":"adas","ad":[1,0],"sras":0,"lras":0,"alt":"AD-AS graph: AD shifts left from AD1 to AD2 so the new equilibrium is on LRAS at a lower price level."}},{"ask":"(d) Suppose instead the government takes no policy action and wages are flexible. Explain how the economy returns to long-run equilibrium, and state what happens to the price level compared with PL1.","pts":["1 point: unemployment is below the natural rate, so nominal wages rise, SRAS shifts left, output returns to Yf and the price level rises above PL1."],"model":{"k":"adas","ad":1,"sras":[0,-1],"lras":0,"alt":"AD-AS graph: SRAS shifts left from SRAS1 to SRAS2 so the new equilibrium is on LRAS at a higher price level."}},{"ask":"(e) Identify one automatic stabilizer in Country Z and explain how it responds to the current inflationary gap without new legislation.","pts":["1 point: progressive income tax collects more revenue as incomes rise (a larger share of income), OR unemployment insurance payments fall as unemployment drops; either slows the growth of disposable income and AD."]}]}
  ];

  const seed = (s) => { let h = 2166136261; for (const ch of s) { h ^= ch.charCodeAt(0); h = Math.imul(h, 16777619); } return h >>> 0; };
  for (const q of QUESTIONS) {
    let a = seed(q.id);
    const r = () => { a = (a + 0x6D2B79F5) >>> 0; let t = a; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
    const order = [0, 1, 2, 3];
    for (let i = 3; i > 0; i--) { const j = Math.floor(r() * (i + 1)); [order[i], order[j]] = [order[j], order[i]]; }
    q.choices = order.map((i) => q.c[i]);
    q.why = order.map((i) => q.why[i]);
    q.answer = order.indexOf(0);
    delete q.c;
  }

  // Graph geometry in a 0-100 box with y pointing up; app.js turns these shapes into SVG.
  // AD/D slope down and SRAS/S slope up through (50 + 15 × offset, 50); LRAS is vertical at 50 + 15 × offset.
  // A [from, to] offset is a shift: the old curve is drawn faint, the new one in color, with an arrow between.
  const ends = (o) => (Array.isArray(o) ? o : [o]);
  const at = (o) => 50 + 15 * o;
  function cross(a, s) { return { x: 50 + 7.5 * (a + s), y: 50 + 7.5 * (a - s) }; }
  function plot(g) {
    const out = [], xl = [], yl = [];
    const line = (cls, x1, y1, x2, y2) => out.push({ t: "line", cls, x1, y1, x2, y2 });
    const text = (x, y, s, anchor = "start", cls = "") => out.push({ t: "text", x, y, s, anchor, cls });
    const arrow = (x1, y1, x2, y2) => out.push({ t: "arrow", x1, y1, x2, y2 });
    if (g.k === "ppc") {
      const curves = ends(g.ppc).map((c) => (Array.isArray(c) ? c : [c, c]));
      curves.forEach(([sx, sy], i) => {
        const cls = curves.length < 2 ? "cur" : i === 0 ? "old" : "new", rx = 80 * sx, ry = 80 * sy;
        if (g.line) line(cls, 0, ry, rx, 0);
        else out.push({ t: "poly", cls, pts: Array.from({ length: 25 }, (_, k) => { const th = (Math.PI / 2) * (k / 24); return [rx * Math.cos(th), ry * Math.sin(th)]; }) });
        const lx = g.line ? rx * 0.62 : rx * Math.cos(0.9), ly = g.line ? ry * 0.38 : ry * Math.sin(0.9);
        text(lx + 3, ly + 3, curves.length > 1 ? "PPC" + (i + 1) : "PPC", "start", cls);
      });
      if (curves.length > 1) {
        const pt = ([sx, sy]) => (g.line ? [40 * sx, 40 * sy] : [80 * sx * Math.SQRT1_2, 80 * sy * Math.SQRT1_2]);
        const [a, b] = [pt(curves[0]), pt(curves[1])], k = b[0] > a[0] || b[1] > a[1] ? 1 : -1;
        arrow(a[0] + 2 * k, a[1] + 2 * k, b[0] - 2 * k, b[1] - 2 * k);
      }
      for (const [x, y, s] of g.pts || []) { out.push({ t: "dot", x, y }); text(x + 2.5, y + 2.5, s, "start", "pt"); }
      return { shapes: out, xl, yl, x: g.x || "Good X", y: g.y || "Good Y" };
    }
    const sd = g.k === "sd", nm = { ad: "AD", sras: "SRAS", lras: "LRAS", d: "D", s: "S", ...(g.names || {}) };
    const down = sd ? "d" : "ad", up = sd ? "s" : "sras";
    const draw = (key, kind) => {
      const list = g[key] === undefined ? [] : ends(g[key]);
      list.forEach((o, i) => {
        const cls = list.length < 2 ? "cur" : i === 0 ? "old" : "new", cx = at(o), name = nm[key] + (list.length > 1 ? i + 1 : "");
        // The second curve of a shift is drawn a little shorter, so its label never sits on top of the first one's.
        if (kind === "v") { line(cls, cx, 3, cx, 90 - 7 * i); text(cx, 93 - 7 * i, name, "middle", cls); }
        else {
          const m = kind === "down" ? -1 : 1, x1 = Math.max(3, cx - 32 + 8 * i), x2 = Math.min(97, cx + 32 - 8 * i);
          line(cls, x1, 50 + m * (x1 - cx), x2, 50 + m * (x2 - cx));
          // An upward curve that moved left would have its label land on the old curve, so that label goes on the left.
          const flip = m > 0 && i > 0 && list[1] < list[0];
          text(flip ? x2 - 2 : x2 + 1.5, 50 + m * (x2 - cx) + (m < 0 ? -1 : 1), name, flip ? "end" : "start", cls);
        }
      });
      if (list.length > 1) {
        const [o1, o2] = list.map(at), d = o2 > o1 ? 1 : -1, y = kind === "v" ? 80 : 72;
        const off = kind === "v" ? 0 : kind === "down" ? 50 - y : y - 50;
        arrow(o1 + off + 2 * d, y, o2 + off - 2 * d, y);
      }
    };
    draw(down, "down"); draw(up, "up"); if (!sd) draw("lras", "v");
    if (g[down] !== undefined && g[up] !== undefined && g.eq !== false) {
      const A = ends(g[down]), S = ends(g[up]);
      const pts = [cross(A[0], S[0])];
      const last = cross(A.at(-1), S.at(-1));
      if (last.x !== pts[0].x || last.y !== pts[0].y) pts.push(last);
      pts.forEach((p, i) => {
        out.push({ t: "guide", x1: 0, y1: p.y, x2: p.x, y2: p.y }, { t: "guide", x1: p.x, y1: 0, x2: p.x, y2: p.y }, { t: "dot", x: p.x, y: p.y });
        xl.push([p.x, (sd ? "Q" : "Y") + (i + 1)]); yl.push([p.y, (sd ? "P" : "PL") + (i + 1)]);
      });
    }
    if (!sd && g.lras !== undefined) xl.push([at(ends(g.lras).at(-1)), "Yf"]);
    // Labels at the same spot share one tick: "Y1 = Yf".
    const merge = (list) => list.reduce((acc, [v, s]) => { const hit = acc.find((e) => Math.abs(e[0] - v) < 0.01); if (hit) hit[1] += " = " + s; else acc.push([v, s]); return acc; }, []);
    return { shapes: out, xl: merge(xl), yl: merge(yl), x: g.x || (sd ? "Quantity" : "Real GDP"), y: g.y || (sd ? "Price" : "PL") };
  }

  window.CL_AP = { courses: { macro: { name: "AP Macroeconomics", units: UNITS, questions: QUESTIONS, frqs: FRQS } }, plot, cross };
})();
